function scrw_catalogue_official() {
	return array(
		'db-opera-series' => array( 'The dBTechnologies OPERA series is a range of two-way active PA loudspeakers available in 10", 12" and 15" versions, each driven by a 600 W RMS Class-D amplifier. A redesigned asymmetrical horn gives an uneven vertical pattern and a double horizontal pattern so coverage stays even from the front rows to the back of the room. Onboard 56-bit DSP with linear-phase FIR filters and an eight-position preset encoder lets the cabinets be tuned for front-of-house, monitor or satellite use without external processing.', 'Series - Speaker type: 2-way active speaker' . "\n" . 'Series - Amplifier: 600 W RMS / 1200 W peak, Class D, SMPS dual-range power supply' . "\n" . 'Series - Controller: 56-bit DSP, 24 bit/48 kHz AD/DA, linear-phase FIR filters' . "\n" . 'Series - Presets: Rotary encoder, 8 presets' . "\n" . 'Series - Limiter: Peak, RMS, Thermal' . "\n" . 'Series - Inputs: 1x Combo (XLR/6.3 mm jack) MIC/Line, 1x Combo (XLR/6.3 mm jack) MIC/Inst' . "\n" . 'Series - Output: 1x XLR male (CH1 Link / Mix out, selectable)' . "\n" . 'Series - Housing: Polypropylene with full metal grille, 36 mm pole mount, 45 degree monitor angle' . "\n" . 'OPERA 10 - Max SPL: 128 dB' . "\n" . 'OPERA 10 - Frequency response [-3 dB]: 70 - 19,600 Hz' . "\n" . 'OPERA 10 - Transducers: HF 1" exit with 1.4" v.c.; LF 1x 10" with 2" v.c.' . "\n" . 'OPERA 10 - Weight: 12.3 kg (27.12 lbs)' . "\n" . 'OPERA 12 - Max SPL: 129 dB' . "\n" . 'OPERA 12 - Frequency response [-3 dB]: 67 - 19,600 Hz' . "\n" . 'OPERA 12 - Frequency response [-10 dB]: 52 - 20,000 Hz' . "\n" . 'OPERA 12 - Transducers: HF 1" exit with 1.4" v.c.; LF 1x 12" with 2" v.c.' . "\n" . 'OPERA 12 - Crossover frequency: 2000 Hz' . "\n" . 'OPERA 12 - Directivity: 100 degrees horizontal (85 up / 120 down), 85 degrees vertical (+25/-60)' . "\n" . 'OPERA 12 - Dimensions (W x H x D): 350 x 642 x 349 mm' . "\n" . 'OPERA 12 - Weight: 14.3 kg (31.53 lbs)' . "\n" . 'OPERA 15 - Max SPL: 130 dB' . "\n" . 'OPERA 15 - Frequency response [-3 dB]: 56 - 19,000 Hz' . "\n" . 'OPERA 15 - Transducers: HF 1" exit with 1.4" v.c.; LF 1x 15" with 2" v.c.' . "\n" . 'OPERA 15 - Weight: 18.3 kg (40.34 lbs)', 'https://www.dbtechnologies.com/us/products/opera' ),
		'db-b-hype-series' => array( 'The dBTechnologies B-Hype series is an entry-level family of two-way active loudspeakers in 8", 10" and 12" formats, each pairing a 1" compression driver with a Class-D amplifier and convection cooling (no fan). The dispersion is asymmetrical on the vertical axis and differentiated top-to-bottom horizontally, which tightens coverage and helps intelligibility in reverberant rooms. A combo input with source-type selection, DSP presets for low and high shelving, and a balanced link output make them easy to use as a standalone box, on a pole, or as a wedge monitor.', 'Series - Speaker type: 2-way active speaker' . "\n" . 'Series - HF driver: 1" compression driver, 1" voice coil' . "\n" . 'Series - Controller: DSP 28/56 bit, 48 kHz' . "\n" . 'Series - Amplifier class: Class D, passive convection cooling' . "\n" . 'Series - Controls: Volume, audio input sensitivity, DSP preset' . "\n" . 'Series - Input / Output: 1x Combo IN (MIC/Line), balanced; 1x XLR OUT (link), balanced' . "\n" . 'Series - Directivity: asymmetrical vertical, differentiated horizontal' . "\n" . 'Series - Housing: full metal grille, pole mount cup, double-wedge 45 degree monitor angle' . "\n" . 'B-Hype 8 - Max SPL: 120 dB' . "\n" . 'B-Hype 8 - Frequency response [-6 dB]: 70 - 19,600 Hz' . "\n" . 'B-Hype 8 - Usable bandwidth [-10 dB]: 65 - 20,000 Hz' . "\n" . 'B-Hype 8 - LF: 1x 8", 1.5" voice coil' . "\n" . 'B-Hype 8 - Amplifier: 260 W peak (130 W RMS)' . "\n" . 'B-Hype 8 - Crossover frequency: 2300 Hz' . "\n" . 'B-Hype 8 - Weight: 6.6 kg (14.55 lbs)' . "\n" . 'B-Hype 10 - Max SPL: 121 dB' . "\n" . 'B-Hype 10 - Frequency response [-6 dB]: 62 - 19,600 Hz' . "\n" . 'B-Hype 10 - Usable bandwidth [-10 dB]: 55 - 20,000 Hz' . "\n" . 'B-Hype 10 - LF: 1x 10", 1.5" voice coil' . "\n" . 'B-Hype 10 - Amplifier: 260 W peak (130 W RMS)' . "\n" . 'B-Hype 10 - Crossover frequency: 2300 Hz' . "\n" . 'B-Hype 10 - Weight: 9 kg (19.84 lbs)' . "\n" . 'B-Hype 12 - Max SPL: 126 dB' . "\n" . 'B-Hype 12 - Frequency response [-6 dB]: 61 - 19,500 Hz' . "\n" . 'B-Hype 12 - Usable bandwidth [-10 dB]: 55 - 20,000 Hz' . "\n" . 'B-Hype 12 - LF: 1x 12", 2" voice coil' . "\n" . 'B-Hype 12 - Amplifier: 400 W peak (200 W RMS)' . "\n" . 'B-Hype 12 - Crossover frequency: 2100 Hz (24 dB/oct.)' . "\n" . 'B-Hype 12 - Dispersion: 85 degrees up / 120 degrees down horizontal; 85 degrees vertical (+25/-60)' . "\n" . 'B-Hype 12 - Dimensions (W x H x D): 350 x 645 x 330 mm' . "\n" . 'B-Hype 12 - Weight: 13.9 kg (30.46 lbs)', 'https://www.dbtechnologies.com/us/products/b-hype' ),
		'db-sub-600-series' => array( 'The dBTechnologies SUB 615 and SUB 618 are bass-reflex active subwoofers built around a 600 W RMS Class-D amplifier with switch-mode power supply, fitted with a 15" and an 18" transducer respectively. Both carry a stereo crossover section with balanced XLR in and out, so a single sub plus two full-range tops forms a complete PA without an external processor. Amp-panel controls cover subwoofer level, mono/stereo output mode, polarity inversion and a low-frequency boost preset, and the plywood cabinets include side handles and an M20 pole thread for stacking tops.', 'Series - Speaker type: Active bass-reflex subwoofer' . "\n" . 'Series - Amplifier: 600 W RMS / 1200 W peak, Class D with SMPS' . "\n" . 'Series - Controller: 28/56 bit DSP' . "\n" . 'Series - Limiter: Peak, Thermal, RMS' . "\n" . 'Series - Controls: Subwoofer level, outputs mode, polarity, subwoofer mode' . "\n" . 'Series - Signal input: 2x XLR (balanced)' . "\n" . 'Series - Signal output: 2x XLR (balanced)' . "\n" . 'Series - Pole mount: M20 thread' . "\n" . 'Series - Directivity: omnidirectional' . "\n" . 'SUB 615 - Max SPL (1 m): 131 dB' . "\n" . 'SUB 615 - Usable bandwidth [-10 dB]: 42 - 124 Hz' . "\n" . 'SUB 615 - LF: 1x 15", 2.5" voice coil' . "\n" . 'SUB 615 - Dimensions (W x H x D): 430 x 580 x 600 mm' . "\n" . 'SUB 615 - Weight: 25.5 kg (56.22 lbs)' . "\n" . 'SUB 618 - Max SPL (1 m): 133 dB' . "\n" . 'SUB 618 - Usable bandwidth [-10 dB]: 35 - 130 Hz' . "\n" . 'SUB 618 - LF: 1x 18", 2.5" voice coil' . "\n" . 'SUB 618 - Dimensions (W x H x D): 500 x 625 x 690 mm' . "\n" . 'SUB 618 - Weight: 31.1 kg (68.57 lbs)', 'https://www.dbtechnologies.com/us/products/sub-series' ),
		'db-flexsys-fmx' => array( 'The dBTechnologies FLEXSYS FMX12 and FMX15 are active two-way coaxial stage monitors driven by 600 W RMS Class-D amplifiers. Their coaxial layout and custom horn deliver a 60 x 90 degree pattern that can be flipped to 90 x 60 degrees simply by rotating the horn, so the wedge matches how the performer works. Advanced DSP with linear-phase FIR filters and eight onboard presets keep the sound even and intelligible, and the plywood wedge cabinets carry a single integrated handle plus a 36 mm side pole mount for use as a satellite top.', 'Series - Speaker type: 2-way active coaxial stage monitor' . "\n" . 'Series - Amplifier: 600 W RMS / 1200 W peak, Class D' . "\n" . 'Series - Controller: DSP 28/56 bit with linear-phase FIR filters' . "\n" . 'Series - Presets: 8 onboard system presets' . "\n" . 'Series - HF driver: 1" with 1.3" voice coil' . "\n" . 'Series - Directivity: 60 x 90 degrees, rotatable horn' . "\n" . 'Series - Pole mount: 36 mm (side panel)' . "\n" . 'Series - Housing: plywood cabinet, front-rear grille design, single integrated handle' . "\n" . 'FMX12 - Max SPL: 128 dB' . "\n" . 'FMX12 - Frequency response [-10 dB]: 52 - 19,000 Hz' . "\n" . 'FMX12 - LF: 1x 12", 2" voice coil' . "\n" . 'FMX12 - Dimensions (W x H x D): 465 x 297 x 444 mm' . "\n" . 'FMX12 - Weight: 13.9 kg (30.6 lbs)' . "\n" . 'FMX15 - Max SPL: 128 dB' . "\n" . 'FMX15 - Frequency response [-10 dB]: 46 - 19,000 Hz' . "\n" . 'FMX15 - LF: 1x 15", 2" voice coil' . "\n" . 'FMX15 - Dimensions (W x H x D): 500 x 340 x 500 mm' . "\n" . 'FMX15 - Weight: 16.9 kg (37.2 lbs)', 'https://www.dbtechnologies.com/us/products/flexsys' ),
		'db-vio-l208-s118' => array( 'The VIO L208 is dBTechnologies\' compact two-way active line array module, using two 8" neodymium woofers and a 1.4" neodymium compression driver behind an all-in-one phase-corrector panel, powered by a 900 W RMS Digipro G3 amplifier. It works as a standalone array for mid-size events or as downfill under the larger VIO L210. Paired with it, the VIO S118 is a flyable horn-loaded active subwoofer with a single 18" neodymium driver and a 1600 W RMS Digipro G4 amplifier, reaching 139 dB max SPL with an onboard cardioid preset, delay and RDNet remote control.', 'VIO L208 - Speaker type: 2-way active line array module' . "\n" . 'VIO L208 - Usable bandwidth [-6 dB]: 75 - 20,000 Hz' . "\n" . 'VIO L208 - Frequency response [+/-3 dB]: 85 - 18,100 Hz' . "\n" . 'VIO L208 - Max SPL (one unit): 133.5 dB' . "\n" . 'VIO L208 - HF: 1x 1.4", 3" v.c., neodymium' . "\n" . 'VIO L208 - LF: 2x 8", 2" v.c., neodymium' . "\n" . 'VIO L208 - Amplifier: 900 W RMS Class-D Digipro G3, convection cooled, auto-range SMPS' . "\n" . 'VIO L208 - Controller: DSP 28/56 bit, 24 bit/48 kHz, linear-phase FIR filters' . "\n" . 'VIO L208 - Horizontal directivity: 100 degrees' . "\n" . 'VIO L208 - I/O: 1x XLR in, 1x XLR out, RDNet RJ45 in/out, PowerCON TRUE1 in/out' . "\n" . 'VIO L208 - Dimensions (W x H x D): 600 x 260 x 390 mm' . "\n" . 'VIO L208 - Weight: 18.1 kg (39.9 lbs)' . "\n" . 'VIO S118 - Speaker type: Active horn-loaded flyable subwoofer' . "\n" . 'VIO S118 - Frequency response [-6 dB]: 39 Hz to crossover frequency' . "\n" . 'VIO S118 - Frequency response [-10 dB]: 36 Hz (HPF)' . "\n" . 'VIO S118 - Max SPL: 139 dB' . "\n" . 'VIO S118 - LF: 1x 18", 4" v.c., neodymium' . "\n" . 'VIO S118 - Amplifier: 1600 W RMS / 3200 W peak Class-D Digipro G4 with PFC' . "\n" . 'VIO S118 - Controller: 32-bit DSP, 24 bit/96 kHz converters' . "\n" . 'VIO S118 - Delay: 0 - 9.9 ms internal, 0.1 ms steps' . "\n" . 'VIO S118 - Crossover: 60 - 110 Hz plus full range, 24 dB/octave' . "\n" . 'VIO S118 - I/O: 1x XLR in, 1x XLR out (link or x-over), RDNet RJ45 in/link, PowerCON TRUE1 in/out' . "\n" . 'VIO S118 - Dimensions (W x H x D): 720 x 520 x 695 mm' . "\n" . 'VIO S118 - Weight: 45.1 kg (99.42 lbs)', 'https://www.dbtechnologies.com/us/products/vio-l/vio-l208' ),
		'yamaha-dbr12' => array( 'The Yamaha DBR12 is a two-way bi-amplified powered loudspeaker with a 12" woofer and a 1" throat compression driver in a lightweight plastic bass-reflex cabinet. Its onboard Class-D amplification delivers 1000 W dynamic power for a maximum output of 131 dB SPL, with FIR-X tuning providing a linear-phase crossover at 2.1 kHz. Two combo inputs, RCA inputs and a selectable through/mix XLR output, plus D-CONTOUR processing and a 35 mm pole socket, let it work as a main, a floor monitor or a side fill.', 'Speaker type: 2-way, bi-amp powered speaker, bass-reflex type' . "\n" . 'Frequency range (-10 dB): 52 Hz - 20 kHz' . "\n" . 'Nominal coverage: 90 degrees horizontal x 60 degrees vertical' . "\n" . 'LF component: 12" cone, 2" voice coil, ferrite magnet' . "\n" . 'HF component: 1.4" diaphragm, 1" throat compression driver, ferrite magnet' . "\n" . 'Crossover: 2.1 kHz, FIR-X tuning (linear-phase FIR filter)' . "\n" . 'Output power: Dynamic 1000 W (LF 800 W, HF 200 W) / Continuous 465 W (LF 400 W, HF 65 W)' . "\n" . 'Maximum output level (1 m, on axis): 131 dB SPL' . "\n" . 'I/O connectors: INPUT1 combo x1, INPUT2 combo x1 plus RCA x2 (unbalanced), OUTPUT XLR3-32 x1 (CH1 through or CH1+CH2 mix)' . "\n" . 'Processors: D-CONTOUR (FOH/MAIN, MONITOR, OFF)' . "\n" . 'Heat dissipation: Fan cooling, 4 speeds' . "\n" . 'Power requirements: 100 V, 100-120 V, 220-240 V, 50/60 Hz' . "\n" . 'Power consumption: 74 W (1/8 power), 18 W idle' . "\n" . 'Cabinet material / finish: Plastic, black' . "\n" . 'Pole socket: 35 mm (bottom x1)' . "\n" . 'Flying and mounting hardware: Bottom x2, rear x1 (M8 x 15 mm eyebolts)' . "\n" . 'Dimensions (W x H x D): 376 x 601 x 348 mm (14.8" x 23.7" x 13.7")' . "\n" . 'Net weight: 15.8 kg (34.8 lbs)', 'https://usa.yamaha.com/products/proaudio/speakers/dbr/index.html' ),
		'yamaha-cbr10' => array( 'The Yamaha CBR10 is the most compact model in the CBR range of passive two-way bass-reflex loudspeakers, combining a 10" woofer with a 1" throat compression driver on a wide-dispersion constant-directivity horn. Rated at 350 W program into 8 ohms, it reaches a calculated maximum of 123 dB SPL and crosses over at 2.8 kHz. The moulded plastic cabinet includes a 50 degree floor-monitor angle, a top handle, two M8 rigging points and a 35 mm pole socket, so it suits both portable work and fixed installation.', 'Speaker type: 2-way passive speaker, bass-reflex type' . "\n" . 'Frequency range (-10 dB): 50 Hz - 20 kHz' . "\n" . 'LF component: 10" cone, 2" voice coil, ferrite magnet' . "\n" . 'HF component: 1" compression driver, 1" throat' . "\n" . 'Crossover frequency: 2.8 kHz' . "\n" . 'Nominal coverage: 90 degrees horizontal x 60 degrees vertical, constant-directivity horn' . "\n" . 'Nominal impedance: 8 ohms' . "\n" . 'Power rating: NOISE 175 W / PGM 350 W / PEAK 700 W' . "\n" . 'Sensitivity (1 W, 1 m on axis): 94 dB SPL' . "\n" . 'Maximum SPL (calculated, 1 m): 123 dB SPL' . "\n" . 'Floor monitor angle: 50 degrees' . "\n" . 'Connectors: 1/4" phone x1, speakON NL4MP x1' . "\n" . 'Rigging points: Bottom x2 (M8 x 15 mm eyebolts)' . "\n" . 'Pole socket: 35 mm (bottom x1)' . "\n" . 'Handle: Top x1' . "\n" . 'Material / finish: Plastic, black' . "\n" . 'Dimensions (W x H x D): 308 x 493 x 389 mm (12.1" x 19.4" x 11.4") with rubber feet' . "\n" . 'Net weight: 9.4 kg (20.7 lbs)', 'https://usa.yamaha.com/products/proaudio/speakers/cbr/index.html' ),
		'yamaha-hs7' => array( 'The Yamaha HS7 is a two-way bi-amplified nearfield studio monitor with a 6.5" cone woofer and a 1" dome tweeter in a bass-reflex MDF cabinet, driven by a 95 W internal amplifier. It is designed for a flat, uncoloured response so mixes translate accurately, with ROOM CONTROL and HIGH TRIM switches to compensate for room placement and desk reflections. Balanced XLR and TRS inputs plus a level control make it straightforward to integrate into any studio setup; the white version is cosmetically identical to the standard black model.', 'Speaker type: 2-way bi-amp powered studio monitor, bass-reflex' . "\n" . 'Frequency range (-10 dB): 43 Hz - 30 kHz' . "\n" . 'Frequency response (-3 dB): 55 Hz - 24 kHz' . "\n" . 'LF component: 6.5" cone' . "\n" . 'HF component: 1" dome tweeter' . "\n" . 'Crossover frequency: 2 kHz' . "\n" . 'Output power: 95 W total (LF 60 W, HF 35 W)' . "\n" . 'I/O connectors: XLR3-31 (balanced), PHONE/TRS (balanced)' . "\n" . 'Controls: LEVEL control (+4 dB, centre click), HIGH TRIM switch (+/- 2 dB at HF), ROOM CONTROL switch (0 / -2 / -4 dB under 500 Hz)' . "\n" . 'Power consumption: 55 W' . "\n" . 'Cabinet material: MDF' . "\n" . 'Dimensions (W x H x D): 210 x 332 x 284 mm (8.3" x 13.1" x 11.2")' . "\n" . 'Net weight: 8.2 kg (18.1 lbs)', 'https://usa.yamaha.com/products/proaudio/speakers/hs_series/index.html' ),
		'yamaha-hs8i' => array( 'The Yamaha HS8I is the install version of the HS8 studio monitor: a two-way bi-amplified bass-reflex speaker with an 8" cone woofer, 1" dome tweeter and 120 W of onboard amplification. Unlike the standard HS8 it carries M8 mounting points on four surfaces, so it can be bracketed to a wall or ceiling in fixed installations such as AV rooms, houses of worship and post-production suites. It keeps the HS-series ROOM CONTROL and HIGH TRIM response switches along with balanced XLR and TRS inputs.', 'Speaker type: 2-way bi-amp powered studio monitor, bass-reflex' . "\n" . 'Frequency response (-10 dB): 38 Hz - 30 kHz' . "\n" . 'Frequency response (-3 dB): 47 Hz - 24 kHz' . "\n" . 'LF component: 8" cone' . "\n" . 'HF component: 1" dome tweeter' . "\n" . 'Crossover frequency: 2 kHz' . "\n" . 'Output power: 120 W total (LF 75 W, HF 45 W)' . "\n" . 'Input sensitivity: -10 dBu / 10k ohms' . "\n" . 'I/O connectors: XLR3-31 (balanced), PHONE/TRS (balanced)' . "\n" . 'Controls: LEVEL control (+4 dB, centre click), HIGH TRIM switch (+/- 2 dB at HF), ROOM CONTROL switch (0 / -2 / -4 dB under 500 Hz)' . "\n" . 'Indicator: Power ON (white LED)' . "\n" . 'Mounting points: Four surfaces x 2 x M8 (120 mm pitch)' . "\n" . 'Optional brackets: K&M 19420 ceiling bracket, K&M 19430 wall bracket' . "\n" . 'Power consumption: 60 W' . "\n" . 'Cabinet material: MDF' . "\n" . 'Dimensions (W x H x D): 250 x 390 x 334 mm (9-13/16" x 15-3/8" x 13-1/8")' . "\n" . 'Net weight: 10.7 kg (23.6 lbs)', 'https://usa.yamaha.com/products/proaudio/speakers/hs_series/index.html' ),
		'dsppa-dsp7011' => array( 'The DSPPA DSP7011 is a 6.5" frameless ceiling speaker with a built-in 70 V/100 V line transformer, intended for distributed background music and paging systems. The high-voltage, low-current line connection allows long cable runs and many speakers in parallel on one amplifier channel, with selectable 6 W or 10 W power taps to balance levels room by room. Its anti-UV engineering plastic housing, fence-style internal structure and supplied spring clamps make it durable and quick to fit into a standard ceiling cutout.', 'Model: DSP7011' . "\n" . 'Type: 6.5 inch frameless ceiling speaker with built-in line transformer' . "\n" . 'Rated power: 10 W' . "\n" . 'Power taps: 6 W / 10 W selectable' . "\n" . 'Input voltage: 70 V / 100 V line (optional)' . "\n" . 'Frequency response: 120 Hz - 16 kHz' . "\n" . 'Sensitivity: 90 dB +/- 2 dB' . "\n" . 'Max SPL: 92 dB +/- 2 dB' . "\n" . 'Distortion (THD): less than 1.5%' . "\n" . 'Dimensions: 185 mm diameter x 74 mm depth' . "\n" . 'Cutout size: 165 - 170 mm diameter' . "\n" . 'Weight: 0.9 kg' . "\n" . 'Housing: anti-UV engineering plastic with fence structure, supplied with mounting clamps', 'https://www.dsppatech.com/product/dsp7011-frameless-10w-ceiling-speaker-with-transfomer.html' ),
		'dsppa-dsp8063b' => array( 'The DSPPA DSP8063B is a 30 W two-way wall-mount speaker with a built-in 70 V/100 V transformer and a rear rotary power tap, so each unit\'s output can be trimmed to suit its position in a distributed system. It pairs a 5" polypropylene woofer with a 1" silk-dome tweeter in a bass-reflex ABS enclosure rated UL94V-0 for fire resistance, behind an anodised aluminium grille. It also accepts a direct 8 ohm low-impedance connection, and ships with a mounting bracket and hanging holes for straightforward wall installation.', 'Model: DSP8063B' . "\n" . 'Type: 2-way wall-mount speaker with built-in 70 V/100 V transformer' . "\n" . 'Speaker units: 5" x1 woofer, 1" x1 tweeter' . "\n" . 'Rated power: 30 W' . "\n" . 'Power taps (70 V): 30 W / 15 W / 8 W / 5 W / 2.5 W' . "\n" . 'Power taps (100 V): 30 W / 15 W / 8 W / 5 W' . "\n" . 'Input: constant voltage 70 V / 100 V, or constant resistance 8 ohms' . "\n" . 'Frequency response: 80 Hz - 20 kHz' . "\n" . 'Sensitivity (1 m, 1 W): 90 dB +/- 2 dB' . "\n" . 'Max SPL (1 m): 105 dB +/- 2 dB' . "\n" . 'Enclosure: UL94V-0 fireproof thickened ABS, black' . "\n" . 'Grille: 1060 pure aluminium, hardened and anti-oxidation treated' . "\n" . 'Dimensions (H x W x D): 280 x 194 x 185 mm' . "\n" . 'Weight: 3.2 kg' . "\n" . 'Mounting: wall bracket with hanging holes, rust-proof treated', 'https://www.dsppatech.com/product/dsp8063b-30w-wall-mount-speaker-with-power-tap.html' ),
		'dsppa-dsp5040' => array( 'The DSPPA DSP5040 is a 40W two-way wall-mount loudspeaker built for commercial public address use, combining a 6.5-inch graphite-cone woofer with a 1-inch silk soft-dome tweeter and DSPPA\'s bass-enhancement radiator design. Its ABS enclosure is rated IP66, so the same model can be installed indoors or in fully exposed outdoor positions, and supplied waterproof brackets make mounting quick. Selectable 70V/100V line-transformer taps plus an 8-ohm bypass let it drop into either a distributed 100V PA loop or a low-impedance amplifier zone.', 'Tweeter: 1" silk soft dome' . "\n" . 'Woofer: 6.5" graphite cone, rubber surround' . "\n" . 'Frequency Range (+/-3 dB): 90Hz-20kHz' . "\n" . 'Power Handling (RMS): 40W' . "\n" . 'Max. SPL: 102dB +/-3dB' . "\n" . 'Sensitivity: 86dB +/-3dB' . "\n" . 'Power Taps (70V): 2.5W-5W-10W-20W' . "\n" . 'Power Taps (100V): 5W-10W-20W-40W' . "\n" . 'Power at 8 Ohm: 40W' . "\n" . 'Impedance: 8 ohms' . "\n" . 'Termination: Pluggable terminal blocks' . "\n" . 'Attachment: Brackets' . "\n" . 'Dimensions (H x W x D): 285mm x 200mm x 195mm' . "\n" . 'Housing Material: ABS' . "\n" . 'Certificate: IP66 waterproof', 'https://www.dsppaaudio.com/products/6-5-inch-40w-ip66-all-weather-wall-mount-speaker-dsp5040/' ),
		'dsppa-dsp455ii' => array( 'The DSPPA DSP455II is a 60W weatherproof column loudspeaker housed in a solid aluminium-alloy enclosure that resists corrosion and deformation, making it suitable for exposed outdoor positions as well as indoor use. It uses four 3-inch full-range polypropylene-cone drivers plus a 2-inch tweeter in a vertical array, which narrows vertical dispersion for better speech intelligibility over distance. A built-in 70V/100V line transformer with selectable power taps allows long cable runs and multiple speakers in parallel on a single distributed PA circuit, and it ships with multifunctional wall-mount brackets.', 'Speaker units: 3" x 4, 2" x 1' . "\n" . 'Rated power (RMS): 60W' . "\n" . 'Frequency response: 140Hz-20kHz' . "\n" . 'Sensitivity (1m, 1W): 89dB +/-3dB' . "\n" . 'Max SPL (1m): 107dB +/-3dB' . "\n" . 'Dimensions (L x W x H): 606 x 109 x 102 mm' . "\n" . 'Net weight: 4kg' . "\n" . 'Transformer: Built-in 70V/100V line transformer with selectable power taps' . "\n" . 'Enclosure: Aluminium alloy, weatherproof' . "\n" . 'Mounting: Supplied metal wall-mount brackets' . "\n" . 'Application: Indoor and outdoor background music and paging', 'https://www.dsppatech.com/product/dsp455ii-outdoor-waterproof-column-speaker.html' ),
		'shure-beta-52a' => array( 'The Shure Beta 52A is a dynamic microphone purpose-built for kick drum and other low-frequency sources, with a response tailored to deliver both low-end weight and clear attack. Its modified supercardioid pattern maintains high gain before feedback and strong off-axis rejection, which helps keep nearby drums and stage wash out of the channel. A built-in locking swivel stand adapter with integral XLR connector holds position even inside a kick drum, and a hardened steel mesh grille protects the capsule under touring conditions.', 'Cartridge Type: Dynamic (moving coil)' . "\n" . 'Frequency Response: 20 to 10,000 Hz' . "\n" . 'Polar Pattern: Supercardioid' . "\n" . 'Output Impedance: 150 Ohms' . "\n" . 'Sensitivity (at 1 kHz, open circuit voltage): -64 dBV/Pa (0.6 mV)' . "\n" . 'Maximum SPL (1 kHz at 1% THD, 1 kOhm load): 174 dB' . "\n" . 'Polarity: Positive pressure on diaphragm produces positive voltage on pin 2 with respect to pin 3' . "\n" . 'Connector: Three-pin professional audio (XLR), male' . "\n" . 'Net Weight: 605 g (1.35 lbs)' . "\n" . 'Grille: Hardened steel mesh' . "\n" . 'Stand Adapter: Integrated dynamic locking swivel mount with integral XLR connector', 'https://www.shure.com/en-US/products/microphones/beta_52a' ),
		'shure-blx288-sm58' => array( 'The Shure BLX288/SM58 is a two-channel analogue wireless system pairing a BLX88 dual receiver with two BLX2 handheld transmitters fitted with SM58 vocal capsules. One-touch QuickScan frequency selection finds a clean channel quickly, and the system works at line-of-sight ranges of up to roughly 100 metres. Each transmitter runs up to 14 hours on two AA batteries, and up to 12 compatible systems can operate in the same frequency band, making it a practical entry-level choice for churches, conference rooms and small-to-mid-size stages.', 'System: Two channels (BLX88 dual receiver + 2 x BLX2/SM58 handheld transmitters)' . "\n" . 'System Operating Range: Up to 300 ft (100 m) line-of-sight' . "\n" . 'System Compatible Channels: Up to 12 per frequency band (region and environment dependent)' . "\n" . 'Transmitter Battery: 2 x AA, up to 14 hours of operation' . "\n" . 'BLX88 Receiver Audio Output Impedance: XLR 200 Ohms; 6.35 mm (1/4") 50 Ohms' . "\n" . 'BLX88 Receiver Audio Output Level (ref. +/-33 kHz deviation, 1 kHz tone): XLR -27 dBV into 100 kOhms; 6.35 mm -13 dBV into 100 kOhms' . "\n" . 'BLX88 Receiver RF Sensitivity: -105 dBm for 12 dB SINAD, typical' . "\n" . 'BLX88 Receiver Image Rejection: >50 dB, typical' . "\n" . 'BLX88 Receiver Dimensions (H x W x D): 40 mm x 388 mm x 116 mm' . "\n" . 'BLX88 Receiver Weight: 429 g (15.1 oz)' . "\n" . 'BLX88 Receiver Housing: Moulded ABS' . "\n" . 'BLX88 Receiver Power Requirements: 12-15 V DC @ 320 mA, external supply (tip positive)' . "\n" . 'SM58 Capsule Type: Dynamic (moving coil)' . "\n" . 'SM58 Capsule Frequency Response: 50 to 15,000 Hz' . "\n" . 'SM58 Capsule Polar Pattern: Cardioid', 'https://www.shure.com/en-US/products/wireless-systems/blx_wireless/blx288-sm58-wireless-dual-vocal-system' ),
		'shure-pga48' => array( 'The Shure PGA48 is an entry-level cardioid dynamic microphone from the PG ALTA series, aimed at spoken word, presentation and karaoke use. Its cartridge is tuned for clear speech reproduction while the cardioid pattern rejects off-axis noise, and an on/off switch gives the user direct control of the channel. It ships with a swivel stand adapter and zip pouch, and is offered with no cable, an XLR-XLR cable or an XLR-to-1/4-inch cable.', 'Type: Dynamic (moving coil)' . "\n" . 'Frequency Response: 70 to 15,000 Hz' . "\n" . 'Polar Pattern: Cardioid' . "\n" . 'Output Impedance: 600 Ohms' . "\n" . 'Sensitivity (at 1 kHz, open circuit voltage): -53.5 dBV/Pa (2.10 mV)' . "\n" . 'Polarity: Positive pressure on diaphragm produces positive voltage on pin 2 with respect to pin 3' . "\n" . 'Switch: On/Off switch' . "\n" . 'Connector: Three-pin professional audio (XLR), male' . "\n" . 'Net Weight: 300 g (10.58 oz)' . "\n" . 'Operating Temperature: -29 to 74 degrees C (-20 to 165 degrees F)' . "\n" . 'Relative Humidity: 0 to 95%' . "\n" . 'Supplied Accessories: Stand adapter, clip, zippered pouch; optional 4.57 m XLR-XLR or XLR-1/4" cable' . "\n" . 'SKU: PGA48-LC (cable options available)', 'https://www.shure.com/en-US/products/microphones/pga48' ),
		'shure-sm58' => array( 'The Shure SM58 is the industry-standard cardioid dynamic vocal microphone, used for live performance, sound reinforcement and studio work. Its frequency response is shaped for voice, with a brightened midrange and bass rolloff that reduce proximity boom, while the uniform cardioid pattern isolates the singer and suppresses background noise. A built-in spherical wind and pop filter, pneumatic shock-mount system and steel mesh grille give it the durability that made it a touring default.', 'Type: Dynamic (moving coil)' . "\n" . 'Frequency Response: 50 to 15,000 Hz' . "\n" . 'Polar Pattern: Cardioid, rotationally symmetrical about microphone axis, uniform with frequency' . "\n" . 'Output Impedance: 300 Ohms' . "\n" . 'Sensitivity (at 1 kHz, open circuit voltage): -56.0 dBV/Pa (1.6 mV)' . "\n" . 'Polarity: Positive pressure on diaphragm produces positive voltage on pin 2 with respect to pin 3' . "\n" . 'Connector: Three-pin professional audio (XLR), male' . "\n" . 'Housing: Enamel-painted die-cast metal with spherical steel mesh grille' . "\n" . 'Net Weight: 298 g (10.5 oz)' . "\n" . 'Shock Mount: Pneumatic shock-mount system' . "\n" . 'Filter: Built-in spherical wind and pop filter' . "\n" . 'Replacement Cartridge: R59' . "\n" . 'Supplied Accessories: A25D swivel stand adapter, 95A2313 storage bag' . "\n" . 'SKU: SM58-LC (also available with XLR-XLR cable)', 'https://www.shure.com/en-US/products/microphones/sm58' ),
		'shure-pga58' => array( 'The Shure PGA58 is a cardioid dynamic handheld microphone from the PG ALTA series, designed for lead and backing vocals at an accessible price point. The cartridge is tuned for natural clarity across the vocal range while the cardioid pattern keeps stage noise and monitor spill out of the channel. It has a black metallic finish, an on/off switch, and comes with a swivel stand adapter and carrying pouch, with or without a cable.', 'Type: Dynamic (moving coil)' . "\n" . 'Frequency Response: 50 to 16,000 Hz' . "\n" . 'Polar Pattern: Cardioid' . "\n" . 'Output Impedance: 150 Ohms' . "\n" . 'Sensitivity (at 1 kHz, open circuit voltage): -55 dBV/Pa (1.79 mV)' . "\n" . 'Polarity: Positive pressure on diaphragm produces positive voltage on pin 2 with respect to pin 3' . "\n" . 'Switch: On/Off switch' . "\n" . 'Connector: Three-pin professional audio (XLR), male' . "\n" . 'Net Weight: 294 g (10.37 oz)' . "\n" . 'Operating Temperature: -29 to 74 degrees C (-20 to 165 degrees F)' . "\n" . 'Relative Humidity: 0 to 95%' . "\n" . 'Supplied Accessories: Swivel stand adapter, carrying pouch; optional XLR-XLR or XLR-1/4" cable', 'https://www.shure.com/en-US/products/microphones/pga58' ),
		'shure-sm7b' => array( 'The Shure SM7B is a cardioid dynamic microphone with a flat, wide-range response that has become a standard for broadcast, podcasting and studio vocals. Switchable bass rolloff and mid-range presence-boost filters let the user shape tone at the microphone, and heavy internal shielding suppresses electromagnetic hum from monitors and nearby equipment. An internal air-suspension shock isolator and a highly effective pop filter keep mechanical noise and plosives out of the recording, and the yoke mount with captive stand nut allows precise positioning.', 'Type: Dynamic (moving coil)' . "\n" . 'Frequency Response: 50 to 20,000 Hz' . "\n" . 'Polar Pattern: Cardioid' . "\n" . 'Output Impedance: 150 Ohms (for connection to mic inputs rated 19 to 300 Ohms)' . "\n" . 'Sensitivity (at 1 kHz, open circuit voltage): -59 dBV/Pa (1.12 mV)' . "\n" . 'Hum Pickup (typical, 60 Hz, equivalent SPL/mOe): 11 dB' . "\n" . 'Switches: Bass rolloff and mid-range presence boost (slotted response selector switches)' . "\n" . 'Cartridge Shock Mount: Internal air-suspension shock and vibration isolator' . "\n" . 'Connector: Three-pin professional audio (XLR)' . "\n" . 'Swivel Assembly: Integrated yoke with captive nut, fits 5/8 in.-27 thread' . "\n" . 'Polarity: Positive pressure on diaphragm produces positive voltage on pin 2 relative to pin 3' . "\n" . 'Housing: Dark grey enamel aluminium and steel case with dark grey foam windscreen' . "\n" . 'Net Weight (with cable): 851.6 g (1.877 lbs)' . "\n" . 'Replacement Cartridge: RPM106' . "\n" . 'Supplied Accessories: A7WS detachable close-talk windscreen, RPM602 switch cover plate', 'https://www.shure.com/en-US/products/microphones/sm7b' ),
		'shure-sm57' => array( 'The Shure SM57 is a cardioid dynamic microphone designed for instrument and amplifier miking, with a contoured response that reproduces drums, percussion, brass, woodwind and guitar cabinets cleanly. Its uniform cardioid pattern isolates the intended source and reduces bleed from the rest of the stage, and it handles very high sound pressure levels without distress. A pneumatic shock-mount system cuts handling and stand-borne noise, and the die-cast steel body stands up to heavy daily use.', 'Type: Dynamic (moving coil)' . "\n" . 'Frequency Response: 40 to 15,000 Hz' . "\n" . 'Polar Pattern: Cardioid, rotationally symmetrical about microphone axis, uniform with frequency' . "\n" . 'Output Impedance: 310 Ohms actual (rated 150 Ohms)' . "\n" . 'Sensitivity (at 1 kHz, open circuit voltage): -56.0 dBV/Pa (1.6 mV)' . "\n" . 'Polarity: Positive pressure on diaphragm produces positive voltage on pin 2 with respect to pin 3' . "\n" . 'Connector: Three-pin professional audio (XLR), male' . "\n" . 'Housing: Dark grey, enamel-painted die-cast steel with polycarbonate grille and stainless steel screen' . "\n" . 'Net Weight: 284 g (10 oz)' . "\n" . 'Dimensions: 157 mm (6-3/16 in.) L x 32 mm (1-1/4 in.) W at widest point' . "\n" . 'Shock Mount: Pneumatic shock-mount system' . "\n" . 'Stand Adapter: Break-resistant, adjustable through 180 degrees' . "\n" . 'SKU: SM57-LC (also available with cable)', 'https://www.shure.com/en-US/products/microphones/sm57' ),
		'shure-pgadrumkit7' => array( 'The Shure PGADRUMKIT7 is a seven-microphone drum package covering a full kit, combining dynamic mics for kick, snare and toms with a pair of condensers for overheads or cymbals. The bundle includes the clips, break-resistant drum rim mounts and XLR cables needed to deploy it, all in a zippered carrying case. It is aimed at houses of worship, schools and small-to-mid-size venues that want a consistent, ready-to-go drum miking solution without specifying mics individually.', 'Kit Contents: 7 microphones (1 x PGA52, 3 x PGA56, 1 x PGA57, 2 x PGA81)' . "\n" . 'PGA52: Cardioid dynamic kick drum microphone (quantity 1)' . "\n" . 'PGA56: Cardioid dynamic snare/tom microphone (quantity 3)' . "\n" . 'PGA57: Cardioid dynamic instrument microphone (quantity 1)' . "\n" . 'PGA81: Cardioid condenser instrument microphone (quantity 2)' . "\n" . 'Microphone Types: Dynamic (PGA52, PGA56, PGA57); condenser (PGA81)' . "\n" . 'Polar Pattern: Cardioid (all included models)' . "\n" . 'A25D Break-resistant Microphone Clip: Included' . "\n" . 'AP56DM Break-resistant Drum Rim Mounts: 3 included' . "\n" . 'Cables: 7 x XLR-XLR, 4.6 m (15 ft)' . "\n" . 'Case: Zippered carrying case included' . "\n" . 'SKU: PGADRUMKIT7', 'https://www.shure.com/en-US/products/bundles/pgadrumkit7' ),
		'shure-blx14-cvl' => array( 'The Shure BLX14/CVL is a single-channel wireless presenter system combining a BLX4 tabletop receiver, a BLX1 bodypack transmitter and a CVL Centraverse cardioid condenser lavalier microphone. The discreet clip-on capsule suits presenters, lecturers and clergy who need to be heard without a visible handheld mic, and its cardioid pattern rejects off-axis noise. One-touch QuickScan frequency selection locates a clean channel, with operating range up to about 100 metres and up to 14 hours of use from two AA batteries.', 'System: Single channel (BLX4 receiver + BLX1 bodypack transmitter + CVL lavalier microphone)' . "\n" . 'System Operating Range: Up to 300 ft (100 m) line-of-sight' . "\n" . 'System Compatible Channels: Up to 12 per frequency band (region and environment dependent)' . "\n" . 'Transmitter Form Factor: Bodypack (BLX1)' . "\n" . 'Transmitter Battery: 2 x AA, up to 14 hours of operation' . "\n" . 'CVL Microphone: Cardioid condenser lavalier, TQG connector' . "\n" . 'BLX4 Receiver Audio Output Impedance: XLR 200 Ohms; 6.35 mm (1/4") 50 Ohms' . "\n" . 'BLX4 Receiver Audio Output Level (ref. +/-33 kHz deviation, 1 kHz tone): XLR -27 dBV into 100 kOhms; 6.35 mm -13 dBV into 100 kOhms' . "\n" . 'BLX4 Receiver RF Sensitivity: -105 dBm for 12 dB SINAD, typical' . "\n" . 'BLX4 Receiver Image Rejection: >50 dB, typical' . "\n" . 'BLX4 Receiver Dimensions (H x W x D): 40 mm x 188 mm x 103 mm' . "\n" . 'BLX4 Receiver Weight: 241 g (8.5 oz)' . "\n" . 'BLX4 Receiver Housing: Moulded ABS' . "\n" . 'BLX4 Receiver Power Requirements: 12-15 V DC @ 160 mA, external supply (tip positive)' . "\n" . 'Frequency Selection: One-touch QuickScan' . "\n" . 'Supplied Accessories: Tie clip and windscreen for CVL lavalier', 'https://www.shure.com/en-US/products/wireless-systems/blx_wireless/blx14-cvl-wireless-cvl-presenter-set' ),
		'shure-blx14-p98h' => array( 'The BLX14/P98H pairs Shure\'s BLX wireless platform with the PGA98H clip-on gooseneck microphone, designed for brass and wind instruments. A BLX1 bodypack transmitter clamps the mic to the instrument bell and sends to a BLX4 single-channel receiver, with one-touch QuickScan frequency selection for fast setup. It is aimed at performers who want a cable-free horn mic with straightforward operation.', 'System type: Single-channel UHF wireless instrument system' . "\n" . 'Microphone: PGA98H clip-on gooseneck condenser (horn/brass)' . "\n" . 'Transmitter: BLX1 bodypack' . "\n" . 'Receiver: BLX4 single-channel (BLX4R half-rack on the BLX14R variant)' . "\n" . 'Operating range: Up to 300 ft (100 m) line of sight' . "\n" . 'Battery life: Up to 14 hours from 2 x AA batteries' . "\n" . 'Frequency selection: One-touch QuickScan scan and sync' . "\n" . 'Compatible channels: Up to 12 channels per frequency band (region/environment dependent)' . "\n" . 'Example SKU: BLX14E/P98H-H8E' . "\n" . 'Included: BLX4 receiver, BLX1 bodypack, PGA98H microphone, clip-on clamp, power supply, 2 AA batteries, user guide', 'https://www.shure.com/en-MEA/products/wireless-systems/blx_wireless/blx14p98h' ),
		'shure-blx188-cvl' => array( 'The BLX188/CVL is a two-channel wireless presenter system built around a BLX88 tabletop dual receiver and two BLX1 bodypack transmitters fitted with CVL lavalier microphones. It lets two speakers share a single receiver, with one-touch scanning to find clear frequencies and up to 14 hours of battery life per transmitter. It suits conference rooms, houses of worship, training rooms and presentation stages.', 'System type: Dual-channel UHF wireless presenter system' . "\n" . 'Microphones: 2 x CVL lavalier condenser' . "\n" . 'Transmitters: 2 x BLX1 bodypack' . "\n" . 'Receiver: BLX88 tabletop dual-channel' . "\n" . 'Operating range: Up to 300 ft (100 m) line of sight' . "\n" . 'Battery life: Up to 14 hours from 2 x AA batteries per transmitter' . "\n" . 'Frequency selection: One-touch QuickScan scan and sync' . "\n" . 'Compatible channels: Up to 12 channels per frequency band (region/environment dependent)' . "\n" . 'Example SKUs: BLX188/CVL-H10 (US), BLX188E/CVL-H8E (MEA/EU)' . "\n" . 'Included: BLX88 dual receiver, 2 BLX1 bodypacks, 2 CVL lavalier mics, 2 lavalier clips, 2 windscreens, PS24 power supply, 2 sets of AA batteries, user guide', 'https://www.shure.com/en-MEA/products/wireless-systems/blx_wireless/blx188-cvl-dual-presenter-set' ),
		'shure-beta-98ds' => array( 'The Beta 98D/S is a miniature condenser microphone built specifically for close-miking snares, toms and percussion. It uses a supercardioid capsule on a flexible gooseneck with the A98D rim mount, giving high gain-before-feedback and strong rejection of nearby drums and cymbals. An in-line RPM626 preamplifier and detachable cable are supplied, and the cartridge is interchangeable with an optional cardioid capsule.', 'Transducer type: Electret condenser' . "\n" . 'Polar pattern: Supercardioid (interchangeable cardioid cartridge available separately)' . "\n" . 'Frequency response: 20 Hz to 20,000 Hz' . "\n" . 'Output impedance: 150 ohms' . "\n" . 'Maximum SPL: 160 dB (2.5 k-ohm load) / 156 dB (1.0 k-ohm load)' . "\n" . 'Dynamic range (typical): 125 dB' . "\n" . 'Signal-to-noise ratio: 59 dB at 94 dB SPL' . "\n" . 'Power requirements: 48 V DC +/-4 V phantom power' . "\n" . 'Preamplifier: RPM626 in-line preamplifier (included)' . "\n" . 'Mount: A98D drum rim mount with flexible gooseneck' . "\n" . 'Cable: Detachable Triple-Flex interconnect cable' . "\n" . 'On/off switch: None' . "\n" . 'Included accessories: Windscreen, storage bag, preamplifier, interconnect cable, A98D drum mount', 'https://www.shure.com/en-US/products/microphones/beta_98ad_c' ),
		'dsppa-rm20' => array( 'The DSPPA RM20 is a two-zone remote paging station for public address systems, designed to work with DSPPA MP600U and MP1000U mixer-amplifiers. Two switches let an operator page either zone independently, and a built-in chime (ascending or descending tone) announces each call. It connects over a single RJ45 cable that carries both signal and power for runs of up to 500 m, so no local power supply is needed at the station.', 'Model: RM20' . "\n" . 'Type: 2-zone remote paging microphone / paging station' . "\n" . 'Sensitivity: +/-10 mV' . "\n" . 'Frequency response: 200 Hz - 15 kHz' . "\n" . 'S/N ratio: >= 60 dB' . "\n" . 'Interface: RJ45, RS485 communication protocol' . "\n" . 'Maximum cable run: Up to 500 m' . "\n" . 'Power supply: Powered by the host amplifier (no separate adapter)' . "\n" . 'Compatible hosts: DSPPA MP600U, MP1000U' . "\n" . 'Chime: 2 types (one ascending tone, one descending tone)' . "\n" . 'Zone control: Individual on/off switch per zone' . "\n" . 'Level indication: Signal level indicator for sound pressure display' . "\n" . 'Microphone volume: Adjustable' . "\n" . 'Dimensions (H x W x D): 40 x 150 x 100 mm' . "\n" . 'Net weight: 0.55 kg', 'https://www.dsppatech.com/product/rm20-2-zones-remote-paging-microphone.html' ),
		'behringer-podcastudio-2-usb' => array( 'The PODCASTUDIO 2 USB is an all-in-one podcasting and home-recording bundle from Behringer. It combines a XENYX 302USB mixer with a built-in USB audio interface and XENYX mic preamp, an XM8500 dynamic vocal microphone with table stand, and HPM1000 studio headphones, plus the cabling and bundled recording software needed to start. It is aimed at podcasters and home recordists who want a ready-to-use kit rather than assembling separate components.', 'Bundle contents: XENYX 302USB mixer, XM8500 dynamic microphone, HPM1000 headphones, microphone table stand, XLR cable, USB cable' . "\n" . 'Mixer: XENYX 302USB, 5-input analog mixer with built-in USB/audio interface' . "\n" . 'Mixer preamp: XENYX studio-grade microphone preamplifier' . "\n" . 'Mixer inputs: 1 x microphone (XLR), 1 x stereo line, 1 x 2-track in, headset connection' . "\n" . 'USB interface channels: 2-channel (stereo) in/out' . "\n" . 'Maximum sample rate: 48 kHz' . "\n" . 'Microphone: XM8500 Ultravoice dynamic, cardioid, with integrated pop filter' . "\n" . 'Headphones: HPM1000 closed-back studio headphones' . "\n" . 'Computer compatibility: PC and Mac (class-compliant USB)' . "\n" . 'Bundled software: Audio recording, editing and podcasting software plus instrument/effect plug-ins' . "\n" . 'Manufacturer part numbers: 000-DZ202-00010 (US), 000-DZ204-00010 (EU)', 'https://www.behringer.com/product.html?modelCode=P0DZ2' ),
		'behringer-c-1u' => array( 'The Behringer C-1U is a side-address studio condenser microphone with a built-in USB interface, so it plugs straight into a PC or Mac without a separate audio interface or phantom power supply. Its cardioid pattern and shock-mounted pressure-gradient capsule give good source separation and feedback rejection for voice, podcasting and acoustic instruments. The microphone draws its power over the same USB connection that carries the audio.', 'Transducer type: Condenser, 16 mm (0.63 in) diaphragm' . "\n" . 'Polar pattern: Cardioid' . "\n" . 'Frequency response: 40 Hz to 20 kHz' . "\n" . 'Maximum SPL: 136 dB (1% THD @ 1 kHz)' . "\n" . 'Capsule: Pressure-gradient transducer, shock-mounted' . "\n" . 'Connector: USB type B' . "\n" . 'Power supply: 5 V, max. 50 mA (via USB)' . "\n" . 'Computer compatibility: PC and Mac; ASIO/WDM drivers available for PC' . "\n" . 'Dimensions: Shaft diameter 54 mm (2.1 in), length 169 mm (6.7 in)' . "\n" . 'Net weight: Approx. 0.53 kg (1.17 lbs)' . "\n" . 'Included: USB cable (type B), swivel stand mount, bundled recording/podcasting software', 'https://www.behringer.com/product.html?modelCode=P0588' ),
		'aver-vc520-pro' => array( 'The AVer VC520 Pro2 is a professional USB conferencing system for mid-to-large meeting rooms, pairing a 1080p PTZ camera with a full-duplex speakerphone. The camera offers 24x total zoom (12x optical), SmartFrame auto-framing and preset-based presenter tracking, while True WDR handles high-contrast lighting. Audio can be expanded by daisy-chaining additional speakerphones or a microphone array to cover larger rooms.', 'Model: VC520 Pro2 (current version of the VC520 Pro)' . "\n" . 'Video resolution: Up to 1920 x 1080 (16:9), also 1600x900, 1280x720, 960x540, 848x480, 800x448, 640x360, 424x240, 320x180; 4:3 modes 800x600, 640x480, 480x360, 320x240' . "\n" . 'Frame rate: Up to 60 fps (also 30 and 15 fps)' . "\n" . 'Zoom: 24x total zoom (12x optical)' . "\n" . 'Field of view (D/H/V): 84.5 / 77.5 / 48 degrees' . "\n" . 'Lens focal length: 3.9 mm (wide) to 47.3 mm (tele)' . "\n" . 'Lens aperture: F1.8 (wide) to F2.8 (tele)' . "\n" . 'Wide dynamic range: True WDR up to 120 dB' . "\n" . 'Minimum focus distance: 1.5 m' . "\n" . 'Framing: SmartFrame auto-framing, Smart Gallery, Preset Framing (presenter follow)' . "\n" . 'Image controls: Mirror, flip, AE and white balance - auto with manual override via PTZApp 2' . "\n" . 'Audio expansion: Additional speakerphones or full-duplex microphone array (see VC520 Pro manual for supported configurations)' . "\n" . 'Mounting/security: Standard tripod screw holes and Kensington slot' . "\n" . 'API: People-counting API for meeting-space utilisation data', 'https://communication.aver.com/model/vc520pro2' ),
		'aver-vc540' => array( 'The AVer VC540 is a 4K conference camera system for medium-to-large rooms, supplied with the FONE540 Bluetooth speakerphone. The camera delivers 4K Ultra HD at 30 fps with 16x zoom, SmartFrame auto-framing and motorised pan/tilt with ten presets, using a Sony sensor and multi-coated optics. The speakerphone connects by USB or Bluetooth, supports IP-based remote management, and can be daisy-chained up to three speakerphones or four microphones for larger spaces.', 'Video resolution: Up to 4K Ultra HD' . "\n" . 'Frame rate: 4K at 30 fps; 1080p, 720p, 640x480, 320x240 at 60, 30 and 15 fps' . "\n" . 'Zoom: 16x total zoom' . "\n" . 'Horizontal field of view: 86 degrees' . "\n" . 'Autofocus: Minimum working distance 1 m' . "\n" . 'Wide dynamic range: True WDR up to 120 dB; backlight compensation and 2D noise reduction' . "\n" . 'Pan / tilt: Pan +/-160 degrees, tilt +90 / -30 degrees; 10 camera presets via remote' . "\n" . 'Framing: AVer SmartFrame automatic field-of-view adjustment' . "\n" . 'Speakerphone: Bluetooth or USB wired, full-duplex 2-microphone array with echo cancellation and advanced noise suppression' . "\n" . 'Speakerphone audio I/O: 3.5 mm phone-in, 3.5 mm line out; can bridge phone-in and USB into one call' . "\n" . 'Speaker output: Adjustable to 90 dB SPL at 0.5 m' . "\n" . 'Expansion: Daisy-chain up to 3 speakerphones or 4 microphones' . "\n" . 'Connectivity: USB 3.1 Type-C (camera), Mini DIN 6 RS-232 (camera), Micro USB (speakerphone), RJ45 IP (speakerphone), Bluetooth' . "\n" . 'Dimensions: Camera 130.7 x 97.8 x 171.1 mm; speakerphone 220 x 181.5 x 49.5 mm; remote 200 x 50 x 21 mm' . "\n" . 'Operating conditions: 0 to 40 C, 20% to 80% humidity' . "\n" . 'Package: 259 x 259 x 349 mm, 4.6 kg' . "\n" . 'Warranty: Camera and speakerphone 3+2 years (with online registration); accessories 1 year' . "\n" . 'Package contents: Cam540 camera, FONE540 speakerphone, remote control, 2 power adapters, power cord, USB 3.1 Type-C to Type-A cable, Micro USB 2.0 to Type-A cable, 3.5 mm aux cable, metal mount and tripod screws, batteries, quick start guide, warranty card', 'https://communication.aver.com/model/vc540' ),
		'yamaha-tf5' => array( 'The Yamaha TF5 is the largest console in the TF series of digital mixers, built around Yamaha\'s TouchFlow Operation touchscreen interface. It provides 48 input mixing channels and 33 motorised faders, with 32 onboard recallable D-PRE mic/line preamps and features such as GainFinder, 1-knob EQ and 1-knob COMP to speed up setup. A built-in 34 x 34 USB 2.0 interface handles multitrack recording, and an expansion slot accepts the NY64-D Dante card.', 'Motor faders: 33 (32 channels + 1 master)' . "\n" . 'Input mixing channels: 48 (40 mono + 2 stereo + 2 return)' . "\n" . 'Buses: 20 Aux (8 mono + 6 stereo) + Stereo + Sub' . "\n" . 'DCA groups: 8, with Roll-out' . "\n" . 'Analog inputs: 32 mic/line XLR/TRS combo + 2 stereo line (RCA pin)' . "\n" . 'Analog outputs: 16 XLR' . "\n" . 'Mic preamps: Recallable D-PRE, max gain +66 dB, load impedance 7.5 k-ohm' . "\n" . 'Input sensitivity: -82 dBu (61.6 uV) to -42 dBu (6.16 mV) max before clip; nominal -62 dBu' . "\n" . 'USB recording: 34 x 34 channels, 24-bit, via USB 2.0 (Type B, TO HOST)' . "\n" . 'USB storage: 2 x 2 record/playback via USB storage device (MP3/WAV playback, WAV record)' . "\n" . 'Onboard processing: 8 effects + 10 GEQ' . "\n" . 'Expansion: 1 slot for NY64-D Dante audio interface card' . "\n" . 'Apps: TF Editor, TF StageMix, MonitorMix; Nuendo Live included' . "\n" . 'Dimensions (W x H x D): 866 x 225 x 599 mm' . "\n" . 'Weight: 20 kg', 'https://usa.yamaha.com/products/proaudio/mixers/tf/index.html' ),
		'yamaha-tf3' => array( 'The Yamaha TF3 is the mid-sized TF series digital mixing console, offering the same 48-channel mixing capacity as the TF5 in a narrower frame with 25 motorised faders. It carries 24 recallable D-PRE mic/line inputs and 16 XLR outputs, and uses the TouchFlow Operation touchscreen with GainFinder and 1-knob EQ/COMP for fast, intuitive setup. Multitrack recording runs over the built-in 34 x 34 USB 2.0 interface, with Dante available through the NY64-D expansion card.', 'Motor faders: 25 (24 channels + 1 master)' . "\n" . 'Input mixing channels: 48 (40 mono + 2 stereo + 2 return)' . "\n" . 'Buses: 20 Aux (8 mono + 6 stereo) + Stereo + Sub' . "\n" . 'DCA groups: 8, with Roll-out' . "\n" . 'Analog inputs: 24 mic/line XLR/TRS combo + 2 stereo line (RCA pin)' . "\n" . 'Analog outputs: 16 XLR' . "\n" . 'Mic preamps: Recallable D-PRE, max gain +66 dB, load impedance 7.5 k-ohm' . "\n" . 'USB recording: 34 x 34 channels, 24-bit, via USB 2.0 (Type B, TO HOST)' . "\n" . 'USB storage: 2 x 2 record/playback via USB storage device (MP3/WAV playback, WAV record)' . "\n" . 'Onboard processing: 8 effects + 10 GEQ' . "\n" . 'Expansion: 1 slot for NY64-D Dante audio interface card' . "\n" . 'Apps: TF Editor, TF StageMix, MonitorMix; Nuendo Live included' . "\n" . 'Power consumption: 110 W' . "\n" . 'Dimensions (W x H x D): 716 x 225 x 599 mm' . "\n" . 'Weight: 17 kg', 'https://usa.yamaha.com/products/proaudio/mixers/tf/index.html' ),
		'yamaha-tf1' => array( 'The Yamaha TF1 is the most compact console in the TF series, small enough to be rack mounted while still offering 40 input mixing channels and 17 motorised faders. It provides 16 recallable D-PRE mic/line inputs and 16 XLR outputs, and shares the series\' TouchFlow Operation touchscreen workflow with GainFinder, 1-knob EQ and 1-knob COMP. Like its larger siblings it includes a 34 x 34 USB 2.0 recording interface and an NY64-D Dante expansion slot.', 'Motor faders: 17 (16 channels + 1 master)' . "\n" . 'Input mixing channels: 40 (32 mono + 2 stereo + 2 return)' . "\n" . 'Buses: 20 Aux (8 mono + 6 stereo) + Stereo + Sub' . "\n" . 'DCA groups: 8, with Roll-out' . "\n" . 'Analog inputs: 16 mic/line XLR/TRS combo + 2 stereo line (RCA pin)' . "\n" . 'Analog outputs: 16 XLR' . "\n" . 'Mic preamps: Recallable D-PRE, max gain +66 dB, load impedance 7.5 k-ohm' . "\n" . 'USB recording: 34 x 34 channels, 24-bit, via USB 2.0 (Type B, TO HOST)' . "\n" . 'USB storage: 2 x 2 record/playback via USB storage device (MP3/WAV playback, WAV record)' . "\n" . 'Onboard processing: 8 effects + 10 GEQ' . "\n" . 'Expansion: 1 slot for NY64-D Dante audio interface card' . "\n" . 'Apps: TF Editor, TF StageMix, MonitorMix; Nuendo Live included' . "\n" . 'Rack mountable: Yes (optional rack-mount kit)' . "\n" . 'Power consumption: 100 W' . "\n" . 'Dimensions (W x H x D): 510 x 225 x 599 mm' . "\n" . 'Weight: 13.5 kg', 'https://usa.yamaha.com/products/proaudio/mixers/tf/index.html' ),
		'yamaha-dm3s' => array( 'The DM3 Standard is Yamaha\'s most compact digital mixing console, built around a 9-inch multi-touch screen and a single Touch & Turn encoder with an 8+1 fader layout. It handles 22 mixing channels (16 mono, 1 stereo and 2 FX returns) at up to 96 kHz, with 16 mic/line inputs, 8 XLR outputs and 18-in/18-out USB streaming and multitrack recording. It is the non-Dante version of the DM3 series, aimed at small live shows, livestreaming and home or location recording.', 'Input channels: 16 mono + 1 stereo + 2 FX return' . "\n" . 'Buses: 1 Stereo, 6 Mix, 2 FX, 2 Matrix (supports Input to Matrix), 1 Cue' . "\n" . 'Analog inputs: 16 mic/line (12 XLR + 4 XLR/TRS combo)' . "\n" . 'Analog outputs: 8 (XLR)' . "\n" . 'Dante: not fitted (Standard model)' . "\n" . 'USB audio: 18 inputs / 18 outputs (USB Type-B, USB 2.0)' . "\n" . 'USB TO DEVICE: 1 (USB Type-A), 2-track recording/playback to USB storage' . "\n" . 'Network: 1 (RJ-45)' . "\n" . 'Effects: 18 effects, GEQ on Mix 1-6 and Stereo' . "\n" . 'User interface: 9-inch multi-touch screen, 9 faders (8 channel + 1 main), 1 Touch and Turn encoder' . "\n" . 'Sampling frequency: 96 kHz / 48 kHz' . "\n" . 'Signal delay: less than 1.3 ms (CH INPUT to OMNI OUT, Fs=96 kHz)' . "\n" . 'Frequency response: +0.5 / -1.0 dB, 20 Hz - 20 kHz' . "\n" . 'Total harmonic distortion: less than 0.01 % (20 Hz - 20 kHz @ +4 dBu into 10 kOhm)' . "\n" . 'Dynamic range: 110 dB typ. (DA converter)' . "\n" . 'Power requirements: DC 24 V / 2.5 A via PA-L500 adapter (100-240 V, 50/60 Hz)' . "\n" . 'Power consumption: 43 W' . "\n" . 'Dimensions (W x H x D): 320 mm x 140 mm x 455 mm' . "\n" . 'Net weight: 6.5 kg (14.3 lb)' . "\n" . 'Operating temperature: 0 to 40 degrees C', 'https://usa.yamaha.com/products/proaudio/mixers/dm3/index.html' ),
		'reloop-elite' => array( 'The Reloop ELITE is a two-channel DVS battle mixer built for Serato DJ Pro and developed with turntablists in mind. It carries 16 oversized velocity-sensitive RGB performance pads covering up to 12 performance modes per deck, three non-contact mini Innofader Pro faders, two OLED displays and a dual 10-in/10-out 24-bit USB interface so two laptops can be connected at once. Serato DJ Pro with the DVS Expansion Pack is unlocked on connection and two NoiseMap control vinyls are included.', 'Type: 2-channel DVS performance / battle mixer for Serato DJ Pro' . "\n" . 'Frequency response: 20 Hz - 20 kHz' . "\n" . 'Audio interface: dual 10 in / 10 out USB 2.0, 24-bit' . "\n" . 'Inputs: 2x phono RCA, 2x line RCA, AUX RCA, mic/line TRS, 2x Smart-Link USB (type A), 2x USB (type B)' . "\n" . 'Outputs: master XLR (balanced), master RCA (unbalanced), booth TRS (balanced), rec RCA (unbalanced), headphones 6.3 / 3.5 mm stereo jack' . "\n" . 'EQ range at 70 Hz, 1 kHz, 13 kHz: -infinity dB (total kill) / +9 dB' . "\n" . 'EQ range mic at 100 Hz, 10 kHz: -12 dB / +12 dB' . "\n" . 'Faders: 3x mini Innofader Pro, non-contact, adjustable curves, reverse (hamster) switch, digital cut-in/out adjustment' . "\n" . 'Performance pads: 16 large velocity-sensitive RGB pads, 4 mode buttons, 3 layers, 12 performance modes' . "\n" . 'Displays: 2 high-contrast OLED displays (FX, BPM, beat divisions, setup menu)' . "\n" . 'Effects: 2 Serato FX units with 3 assignable slots plus stand-alone Tweak FX (Filter, Crush, Flanger, White Noise, user mode)' . "\n" . 'Chassis: metal construction, deep black metallic hard-wearing finish, Kensington lock' . "\n" . 'Dimensions (W x D x H): 290 mm x 414 mm x 107.5 mm (potentiometers 18.5 mm)' . "\n" . 'Weight: 6 kg' . "\n" . 'Software requirements: Serato DJ Pro 2.1.2 or later' . "\n" . 'Included: full Serato DJ Pro with DVS Expansion Pack, 2x Serato control vinyls with NoiseMap, USB cable, power cord, manual, 90-day BPM Supreme membership', 'https://www.reloop.com/reloop-elite' ),
		'yamaha-mg06x' => array( 'The MG06X is the smallest mixer in Yamaha\'s MG series: a 6-channel analogue desk with two mono mic/line channels on combo jacks and two stereo line channels. The mono channels use Yamaha\'s class-A D-PRE preamps with a PAD switch, 80 Hz high-pass filter and 2-band EQ, and a built-in SPX effects processor offers six programs. It runs from an external adapter and is light enough for mobile use, interviews, small events and desktop setups.', 'Channels: 6-channel analogue mixing console (max. 2 mic / 6 line inputs)' . "\n" . 'Input channels: 2 mono [MIC/LINE], 2 stereo [LINE]' . "\n" . 'Bus: 1 stereo' . "\n" . 'Output channels: STEREO OUT 2, PHONES 1 (no MONITOR OUT, no AUX SEND, no GROUP OUT)' . "\n" . 'On-board processors: SPX algorithm, 6 programs' . "\n" . 'Phantom power: +48 V' . "\n" . 'Digital I/O: none (no USB audio)' . "\n" . 'PAD: 26 dB (mono)' . "\n" . 'HPF: 80 Hz, 12 dB/oct (mono)' . "\n" . 'EQ HIGH: +/-15 dB, 10 kHz shelving (mono)' . "\n" . 'EQ LOW: +/-15 dB, 100 Hz shelving (mono)' . "\n" . 'Level meter: 2 x 7-segment LED [PEAK, +6, +3, 0, -3, -10, -20 dB]' . "\n" . 'Total harmonic distortion: 0.01 % @ +8 dBu (20 Hz - 20 kHz), GAIN min' . "\n" . 'Frequency response: +0.5 / -0.5 dB (20 Hz - 20 kHz)' . "\n" . 'Equivalent input noise: -128 dBu (mono input, Rs 150 ohm, GAIN max)' . "\n" . 'Crosstalk: -88 dB' . "\n" . 'Power requirements: PA-130 (DC 12 V / 1.0 A) or MU18 (DC 12 V / 1.5 A) adapter' . "\n" . 'Power consumption: 12 W' . "\n" . 'Dimensions (W x H x D): 149 mm x 62 mm x 202 mm' . "\n" . 'Net weight: 0.9 kg (1.98 lbs)' . "\n" . 'Operating temperature: 0 to +40 degrees C', 'https://usa.yamaha.com/products/proaudio/mixers/mg_series_xu_model/index.html' ),
		'yamaha-mg10xu' => array( 'The MG10XU is a compact 10-channel analogue mixer with four mono mic/line combo inputs on D-PRE preamps plus three stereo line channels. Each mono channel gets 3-band EQ, a high-pass filter and Yamaha\'s 1-knob compressor, and the desk includes an SPX effects engine with 24 programs. A 24-bit/192 kHz 2-in/2-out USB audio interface makes it straightforward to record rehearsals or stream, and Cubase AI is included as a download.', 'Channels: 10-channel analogue mixing console (max. 4 mic / 10 line inputs)' . "\n" . 'Input channels: 4 mono [MIC/LINE], 3 stereo [LINE]' . "\n" . 'Bus: Stereo 1, AUX [FX] 1' . "\n" . 'Output channels: STEREO OUT 2, MONITOR OUT 1, PHONES 1, AUX SEND 1' . "\n" . 'On-board processors: SPX algorithm, 24 programs' . "\n" . 'Phantom power: +48 V' . "\n" . 'Digital I/O: USB Audio Class 2.0, max 192 kHz, 24-bit (2-in / 2-out)' . "\n" . 'PAD: 26 dB (mono)' . "\n" . 'HPF: 80 Hz, 12 dB/oct (mono)' . "\n" . 'Compressor: 1-knob, threshold +22 dBu to -8 dBu, ratio 1:1 to 4:1, output 0-7 dB, attack approx. 25 ms, release approx. 300 ms' . "\n" . 'EQ: HIGH 10 kHz shelving, MID 2.5 kHz peaking, LOW 100 Hz shelving, all +/-15 dB' . "\n" . 'Level meter: 2 x 7-segment LED [PEAK, +10, +6, 0, -6, -10, -20 dB]' . "\n" . 'Total harmonic distortion: 0.02 % @ +14 dBu (20 Hz - 20 kHz), GAIN min' . "\n" . 'Frequency response: +0.5 / -1.0 dB (20 Hz - 48 kHz)' . "\n" . 'Equivalent input noise: -128 dBu (mono input, Rs 150 ohm, GAIN max)' . "\n" . 'Crosstalk: -83 dB' . "\n" . 'Power requirements: PA-10 adapter (AC 38 VCT, 0.62 A)' . "\n" . 'Power consumption: 22.9 W' . "\n" . 'Dimensions (W x H x D): 244 mm x 71 mm x 294 mm' . "\n" . 'Net weight: 2.1 kg (4.63 lbs)' . "\n" . 'Included accessories: AC adaptor, owner\'s manual, Cubase AI download information, technical specifications', 'https://usa.yamaha.com/products/proaudio/mixers/mg_series_xu_model/index.html' ),
		'yamaha-mg12xu' => array( 'The MG12XU is a 12-channel analogue mixer offering four mono mic/line combo channels, two mono/stereo channels and two stereo line channels, with up to six mic inputs in total. It adds two group buses and two aux sends over the smaller MG models, and every mono channel carries 3-band EQ, a high-pass filter and a 1-knob compressor. An SPX processor with 24 programs and a 24-bit/192 kHz 2-in/2-out USB interface cover effects and computer recording.', 'Channels: 12-channel analogue mixing console (max. 6 mic / 12 line inputs)' . "\n" . 'Input channels: 4 mono [MIC/LINE], 2 mono/stereo [MIC/LINE], 2 stereo [LINE]' . "\n" . 'Bus: Stereo 1, GROUP 2, AUX 2 (incl. FX)' . "\n" . 'Output channels: STEREO OUT 2, MONITOR OUT 1, PHONES 1, AUX SEND 2, GROUP OUT 2' . "\n" . 'On-board processors: SPX algorithm 24 programs, PARAMETER control 1, FOOT SW 1 (FX RTN CH on/off)' . "\n" . 'Phantom power: +48 V' . "\n" . 'Digital I/O: USB Audio Class 2.0, max 192 kHz, 24-bit (2-in / 2-out)' . "\n" . 'PAD: 26 dB (mono)' . "\n" . 'HPF: 80 Hz, 12 dB/oct (mono/stereo: MIC only)' . "\n" . 'Compressor: 1-knob (gain/threshold/ratio), threshold +22 dBu to -8 dBu, ratio 1:1 to 4:1, attack approx. 25 ms, release approx. 300 ms' . "\n" . 'EQ: HIGH 10 kHz shelving, MID 2.5 kHz peaking, LOW 100 Hz shelving, all +/-15 dB' . "\n" . 'Level meter: 2 x 12-segment LED [PEAK, +10, +6, +3, 0, -3, -6, -10, -15, -20, -25, -30 dB]' . "\n" . 'Total harmonic distortion: 0.03 % @ +14 dBu (20 Hz - 20 kHz), GAIN min' . "\n" . 'Frequency response: +0.5 / -1.5 dB (20 Hz - 48 kHz)' . "\n" . 'Equivalent input noise: -128 dBu (mono input, Rs 150 ohm, GAIN max)' . "\n" . 'Crosstalk: -78 dB' . "\n" . 'Power requirements: AC 100 - 240 V, 50/60 Hz (internal universal supply)' . "\n" . 'Power consumption: 22 W' . "\n" . 'Dimensions (W x H x D): 308 mm x 118 mm x 422 mm' . "\n" . 'Net weight: 4.2 kg (9.3 lbs)' . "\n" . 'Accessories: owner\'s manual, technical specifications, AC power cord, Cubase AI download information; optional rack-mount kit RK-MG12, foot switch FC5', 'https://usa.yamaha.com/products/proaudio/mixers/mg_series_xu_model/index.html' ),
		'yamaha-mg16xu' => array( 'The MG16XU is a 16-channel analogue mixer with eight mono mic/line combo channels, two mono/stereo channels and two stereo line channels, for up to ten microphone inputs. It provides four group buses and four aux sends, making it suitable for bands, houses of worship and installed PA work where separate monitor and effects feeds are needed. D-PRE preamps, 1-knob compressors, an SPX engine with 24 programs, 24-bit/192 kHz USB audio and a metal chassis with rack-mount kit are all standard.', 'Channels: 16-channel analogue mixing console (max. 10 mic / 16 line inputs)' . "\n" . 'Input channels: 8 mono [MIC/LINE], 2 mono/stereo [MIC/LINE], 2 stereo [LINE]' . "\n" . 'Bus: Stereo 1, GROUP 4, AUX 4 (incl. FX)' . "\n" . 'Output channels: STEREO OUT 2, MONITOR OUT 1, PHONES 1, AUX SEND 4, GROUP OUT 4' . "\n" . 'On-board processors: SPX algorithm 24 programs, PARAMETER control 1, FOOT SW 1 (FX RTN CH on/off)' . "\n" . 'Phantom power: +48 V' . "\n" . 'Digital I/O: USB Audio Class 2.0, max 192 kHz, 24-bit (2-in / 2-out)' . "\n" . 'PAD: 26 dB (mono)' . "\n" . 'HPF: 80 Hz, 12 dB/oct (mono/stereo: MIC only)' . "\n" . 'Compressor: 1-knob (gain/threshold/ratio), threshold +22 dBu to -8 dBu, ratio 1:1 to 4:1, attack approx. 25 ms, release approx. 300 ms' . "\n" . 'EQ: HIGH 10 kHz shelving, MID mono 250 Hz - 5 kHz peaking / stereo 2.5 kHz peaking, LOW 100 Hz shelving, all +/-15 dB' . "\n" . 'Level meter: 2 x 12-segment LED [PEAK, +10, +6, +3, 0, -3, -6, -10, -15, -20, -25, -30 dB]' . "\n" . 'Total harmonic distortion: 0.03 % @ +14 dBu (20 Hz - 20 kHz), GAIN min' . "\n" . 'Frequency response: +0.5 / -1.5 dB (20 Hz - 48 kHz)' . "\n" . 'Equivalent input noise: -128 dBu (mono input, Rs 150 ohm, GAIN max)' . "\n" . 'Crosstalk: -78 dB' . "\n" . 'Power requirements: AC 100 - 240 V, 50/60 Hz (internal universal supply)' . "\n" . 'Power consumption: 30 W' . "\n" . 'Dimensions (W x H x D): 444 mm x 130 mm x 500 mm' . "\n" . 'Net weight: 6.8 kg (15.0 lbs)' . "\n" . 'Accessories: owner\'s manual, technical specifications, AC power cord, Cubase AI download information, rack-mount kit included; optional foot switch FC5', 'https://usa.yamaha.com/products/proaudio/mixers/mg_series_xu_model/index.html' ),
		'yamaha-mg20xu' => array( 'The MG20XU is the largest mixer in Yamaha\'s MG series, offering 20 line inputs with twelve mono mic/line combo channels and four mono/stereo channels for up to sixteen microphones. Four group buses and four aux sends give it the routing depth needed for larger live and installed systems, and each mono channel has a 1-knob compressor, high-pass filter and sweepable mid EQ. It includes an SPX effects processor with 24 programs, 24-bit/192 kHz USB audio and a rack-mount kit in a metal chassis.', 'Channels: 20-channel analogue mixing console (max. 16 mic / 20 line inputs)' . "\n" . 'Input channels: 12 mono [MIC/LINE], 4 mono/stereo [MIC/LINE]' . "\n" . 'Bus: Stereo 1, GROUP 4, AUX 4 (incl. FX)' . "\n" . 'Output channels: STEREO OUT 2, MONITOR OUT 1, PHONES 1, AUX SEND 4, GROUP OUT 4' . "\n" . 'On-board processors: SPX algorithm 24 programs, PARAMETER control 1, FOOT SW 1 (FX RTN CH on/off)' . "\n" . 'Phantom power: +48 V' . "\n" . 'Digital I/O: USB Audio Class 2.0, max 192 kHz, 24-bit (2-in / 2-out)' . "\n" . 'PAD: 26 dB (mono)' . "\n" . 'HPF: 80 Hz, 12 dB/oct (mono/stereo: MIC only)' . "\n" . 'Compressor: 1-knob (gain/threshold/ratio), threshold +22 dBu to -8 dBu, ratio 1:1 to 4:1, attack approx. 25 ms, release approx. 300 ms' . "\n" . 'EQ: HIGH 10 kHz shelving, MID mono 250 Hz - 5 kHz peaking / stereo 2.5 kHz peaking, LOW 100 Hz shelving, all +/-15 dB' . "\n" . 'Level meter: 2 x 12-segment LED [PEAK, +10, +6, +3, 0, -3, -6, -10, -15, -20, -25, -30 dB]' . "\n" . 'Total harmonic distortion: 0.03 % @ +14 dBu (20 Hz - 20 kHz), GAIN min' . "\n" . 'Frequency response: +0.5 / -1.5 dB (20 Hz - 48 kHz)' . "\n" . 'Equivalent input noise: -128 dBu (mono input, Rs 150 ohm, GAIN max)' . "\n" . 'Crosstalk: -78 dB' . "\n" . 'Power requirements: AC 100 - 240 V, 50/60 Hz (internal universal supply)' . "\n" . 'Power consumption: 36 W' . "\n" . 'Dimensions (W x H x D): 444 mm x 130 mm x 500 mm' . "\n" . 'Net weight: 7.1 kg (15.7 lbs)' . "\n" . 'Accessories: owner\'s manual, technical specifications, AC power cord, Cubase AI download information, rack-mount kit included; optional foot switch FC5', 'https://usa.yamaha.com/products/proaudio/mixers/mg_series_xu_model/index.html' ),
		'yamaha-mgp24x' => array( 'The MGP24X is Yamaha\'s 24-channel premium analogue console, with sixteen mic inputs on switchable phantom power and sixteen mono plus four stereo line channels. Routing is generous for an analogue desk: six aux sends, two FX sends, four group buses plus the stereo bus, two matrix outputs and a mono output. Two separate on-board processors handle effects, a REV-X reverb engine and a 16-program SPX engine, and an iPod/iPhone USB port allows playback and control via the MGP Editor app.', 'Mixing channels: 24 line inputs (16 mono and 4 stereo)' . "\n" . 'Mic inputs: 16 (input HPF 100 Hz, 12 dB/oct)' . "\n" . 'Phantom power: 48 V per channel' . "\n" . 'Groups: 4 GROUP buses + ST bus' . "\n" . 'AUX: 6 AUX sends + 2 FX sends' . "\n" . 'Matrix: 1 matrix out (2 matrix output jacks)' . "\n" . 'On-board processors: FX1 REV-X (8 programs, parameter control), FX2 SPX (16 programs, parameter control)' . "\n" . 'Line inputs / inserts: LINE 16 mono + 4 stereo, CH INSERT 16, RETURN 1 stereo' . "\n" . 'Digital I/O: USB device, iPod / iPhone' . "\n" . 'Main outputs: ST OUT L/R (XLR + phone), MONO OUT (XLR), GROUP OUT 1-4, AUX SEND 1-6, MATRIX OUT 1-2, MONITOR OUT L/R, PHONES' . "\n" . 'Total harmonic distortion: 0.02 % (20 Hz - 20 kHz @ +14 dBu)' . "\n" . 'Frequency response: +0.5 / -1.0 dB, 20 Hz - 20 kHz @ nominal output, 1 kHz' . "\n" . 'Equivalent input noise: -128 dBu' . "\n" . 'Residual output noise: -92 dBu' . "\n" . 'Crosstalk: -74 dB @ 1 kHz' . "\n" . 'Power requirements: 100 - 240 V, 50/60 Hz' . "\n" . 'Power consumption: 86 W max' . "\n" . 'Dimensions (W x H x D): 819 mm x 169 mm x 565 mm (32.2" x 6.7" x 22.2")' . "\n" . 'Net weight: 15.5 kg (34.2 lb)' . "\n" . 'Talkback: dedicated talkback mic input (XLR)', 'https://usa.yamaha.com/products/proaudio/mixers/mgp/index.html' ),
		'yamaha-mgp32x' => array( 'The MGP32X is the flagship of Yamaha\'s MGP premium analogue range, carrying 32 line inputs made up of 24 mono and 4 stereo channels with 24 mic preamps and per-channel 48 V phantom power. It offers six aux sends plus two FX sends, four group buses with the stereo bus, matrix and mono outputs, and 24 channel inserts for outboard processing. Dual on-board processors provide REV-X reverb and SPX multi-effects, and an iPod/iPhone USB port supports playback and MGP Editor control.', 'Mixing channels: 32 line inputs (24 mono and 4 stereo)' . "\n" . 'Mic inputs: 24 (input HPF 100 Hz, 12 dB/oct)' . "\n" . 'Phantom power: 48 V per channel' . "\n" . 'Groups: 4 GROUP buses + ST bus' . "\n" . 'AUX: 6 AUX sends + 2 FX sends' . "\n" . 'Matrix: 1 matrix out (2 matrix output jacks)' . "\n" . 'On-board processors: FX1 REV-X (8 programs, parameter control), FX2 SPX (16 programs, parameter control)' . "\n" . 'Line inputs / inserts: LINE 24 mono + 4 stereo, CH INSERT 24, RETURN 1 stereo' . "\n" . 'Digital I/O: USB device, iPod / iPhone' . "\n" . 'Main outputs: ST OUT L/R (XLR + phone), MONO OUT (XLR), GROUP OUT 1-4, AUX SEND 1-6, MATRIX OUT 1-2, MONITOR OUT L/R, PHONES' . "\n" . 'Total harmonic distortion: 0.02 % (20 Hz - 20 kHz @ +14 dBu)' . "\n" . 'Frequency response: +0.5 / -1.0 dB, 20 Hz - 20 kHz @ nominal output, 1 kHz' . "\n" . 'Equivalent input noise: -128 dBu' . "\n" . 'Residual output noise: -92 dBu' . "\n" . 'Crosstalk: -74 dB @ 1 kHz' . "\n" . 'Power requirements: 100 - 240 V, 50/60 Hz' . "\n" . 'Power consumption: 86 W max' . "\n" . 'Dimensions (W x H x D): 1,027 mm x 169 mm x 565 mm (40.4" x 6.7" x 22.2")' . "\n" . 'Net weight: 19 kg (41.9 lb)' . "\n" . 'Talkback: dedicated talkback mic input (XLR)', 'https://usa.yamaha.com/products/proaudio/mixers/mgp/index.html' ),
		'yamaha-c40' => array( 'The C40 is Yamaha\'s full-size nylon-string classical guitar and one of the most widely recommended first instruments for students. It uses a spruce top with a rosewood fingerboard and bridge on Yamaha\'s CG body shape, with a 650 mm scale length and a 52 mm nut width typical of classical guitars. The body is gloss finished and the neck matt, and the tone and playability are unusually good for its price.', 'Body shape: Yamaha CG shape' . "\n" . 'Scale length: 650 mm (25 9/16")' . "\n" . 'Body length: 490 mm' . "\n" . 'Total length: 995 mm' . "\n" . 'Body width: 370 mm' . "\n" . 'Body depth: 94 - 100 mm' . "\n" . 'Nut width: 52 mm' . "\n" . 'String spacing: 11.8 mm' . "\n" . 'Top material: spruce' . "\n" . 'Back material: locally sourced tonewood' . "\n" . 'Side material: locally sourced tonewood' . "\n" . 'Neck material: locally sourced tonewood' . "\n" . 'Fingerboard material: rosewood' . "\n" . 'Fingerboard radius: flat' . "\n" . 'Bridge material: rosewood' . "\n" . 'Nut material: urea' . "\n" . 'Saddle material: urea' . "\n" . 'Bridge pins: none' . "\n" . 'Tuners: chrome (RM-1252X)' . "\n" . 'Body binding: black (black + white on BL colour variation)' . "\n" . 'Body finish: gloss; neck finish: matt' . "\n" . 'Strings: medium' . "\n" . 'Electronics: none', 'https://yamaha.co.za/product/c40ii/' ),
		'yamaha-f310' => array( 'The F310 is Yamaha\'s entry-level full-size steel-string acoustic, built on a traditional Western dreadnought body with a spruce top and rosewood fingerboard and bridge. Its slightly shorter 634 mm scale and slim neck make it comfortable for newer players without thinning out the sound. It is offered in several finishes including Natural, Black and Tobacco Brown Sunburst.', 'Body shape: traditional Western' . "\n" . 'Scale length: 634 mm (25")' . "\n" . 'Body length: 505 mm (19 7/8")' . "\n" . 'Total length: 1029 mm (40 1/2")' . "\n" . 'Body width: 412 mm (16 1/4")' . "\n" . 'Body depth: 96 - 116 mm (3 13/16" - 4 9/16")' . "\n" . 'Nut width: 43 mm (1 11/16")' . "\n" . 'String spacing: 10.0 mm' . "\n" . 'Top material: spruce' . "\n" . 'Back material: locally sourced tonewood' . "\n" . 'Fingerboard material: rosewood' . "\n" . 'Fingerboard radius: R400 mm (15 3/4")' . "\n" . 'Bridge material: rosewood' . "\n" . 'Nut material: urea' . "\n" . 'Saddle material: urea' . "\n" . 'Bridge pins: black ABS' . "\n" . 'Tuners: covered chrome (TM-14P)' . "\n" . 'Body binding: black' . "\n" . 'Strings: .012 / .016 / .024 / .032 / .042 / .053' . "\n" . 'Accessories: hex wrench' . "\n" . 'Colours available: Natural, Black, Tobacco Brown Sunburst', 'https://yamaha.co.za/product/f310/' ),
		'encore-e99blk' => array( 'The Encore E99 is a single-cutaway, solid-body electric guitar aimed at beginners and early-intermediate rock players, designed by Trev Wilkinson with the UK Encore design team. It pairs an archtop basswood body and set maple neck with two humbucking pickups, a Tune-O-Matic bridge and stop-bar tailpiece for a thick, high-gain voice. The drop-shoulder body and offset heel give easier access to the upper frets than most guitars in its class. Supplied in a gloss black finish.', 'Body: Solid archtop basswood' . "\n" . 'Neck: Maple, set-neck' . "\n" . 'Fingerboard: 22 fret' . "\n" . 'Scale Length: 630 mm' . "\n" . 'Tuners: Diecast Guitar Tech' . "\n" . 'Bridge: Tune-O-Matic' . "\n" . 'Tailpiece: Stop bar' . "\n" . 'Pickups: 2 Guitar Tech double coils (humbuckers)' . "\n" . 'Controls: 2 Tone, 2 Volume' . "\n" . 'Finish: Gloss Black' . "\n" . 'Model code: E99BLK', '' ),
		'odyssey-debut-clarinet' => array( 'The Odyssey Debut OCL120 is a student Bb clarinet outfit designed by British master craftsman Peter Pollard for easy blowing and reliable tone at a beginner-friendly price. It uses a durable ABS body with a wood-grain finish and nickel-plated keywork on stainless steel rods, springs and pins, and ships with two barrels plus a mouthpiece. The outfit includes a plush-lined, hard-foam backpack-style case with shoulder straps, a cleaning cloth and cork grease.', 'SKU: OCL120' . "\n" . 'Key: Bb' . "\n" . 'Keys: 17 keys' . "\n" . 'Body material: ABS' . "\n" . 'Body finish: Wood grain effect' . "\n" . 'Keywork: Nickel-plated keys' . "\n" . 'Rods, springs and pins: Stainless steel' . "\n" . 'Pads and mouthpiece: Quality pads and mouthpiece included' . "\n" . 'Barrels: Two barrels supplied' . "\n" . 'Case: Zero-gravity hard foam \'backpack\', plush lined, with shoulder straps' . "\n" . 'Accessories: Cleaning cloth, cork grease, instruction leaflet' . "\n" . 'Designer: Peter Pollard / UK Odyssey design team' . "\n" . 'RRP (JHS): GBP 229', 'https://www.jhs.co.uk/products/odyssey-debut-bb-clarinet-outfit' ),
		'pp-half-moon-tambourine' => array( 'The PP World PP4011 is a headless half-moon tambourine in black plastic, intended for hand percussion use in classrooms, worship groups and general band work. It carries 16 pairs of jingles for a bright, cutting sound, and an inset padded handle that makes extended playing more comfortable. Overall diameter is 8.5 inches (21.5 cm).', 'SKU: PP4011' . "\n" . 'Brand: PP World (Performance Percussion)' . "\n" . 'Type: Headless half-moon tambourine' . "\n" . 'Jingles: 16 pairs' . "\n" . 'Handle: Inset padded handle' . "\n" . 'Overall size: 8.5 in / 21.5 cm diameter' . "\n" . 'Colour: Black' . "\n" . 'RRP (JHS): GBP 9.99', 'https://www.jhs.co.uk/products/pp-world-headless-tambourine-black' ),
		'yamaha-psr-sx920' => array( 'The PSR-SX920 is the flagship model of Yamaha\'s PSR-SX arranger workstation range, built around a 61-note organ-style keyboard and a 7-inch colour touchscreen. It is the first SX-series instrument to include Super Articulation2 voices alongside Super Articulation+ and the new Crossfade Portamento, giving unusually lifelike instrument articulations, and it carries over 1,500 voices with 575 accompaniment styles. Performance tools include Chord Looper, Style Dynamics Control, a vocal harmony and synth vocoder engine, assignable live-control knobs and buttons, and USB audio recording.', 'Number of Keys: 61' . "\n" . 'Keyboard Type: Organ (FSB), Initial Touch' . "\n" . 'Touch Response: Normal, Soft1, Soft2, Hard1, Hard2' . "\n" . 'Display: TFT Color Wide VGA LCD, 800 x 480 dots (7 inch), touch screen' . "\n" . 'Tone Generating Technology: AWM Stereo Sampling, AEM technology' . "\n" . 'Maximum Polyphony: 128' . "\n" . 'Preset Voices: 1,587 Voices + 63 Drum/SFX Kits + 480 XG Voices' . "\n" . 'Featured Voices: 12 S.Articulation2, 15 S.Articulation+, 340 S.Articulation, 55 OrganFlutes, 82 MegaVoice, 31 Sweet!, 87 Cool!, 149 Live!' . "\n" . 'Preset Styles: 575 (520 Pro, 49 Session, 6 Free Play)' . "\n" . 'Vocal Harmony: 54 Vocal Harmony presets, 20 Synth Vocoder presets' . "\n" . 'Internal Memory: Approx. 4 GB' . "\n" . 'Expansion Voice Capacity: Approx. 2 GB' . "\n" . 'Amplifiers: (15 W + 10 W) x 2' . "\n" . 'Speakers: 13 cm x 2 + 2.5 cm (dome) x 2' . "\n" . 'Connectivity: MIDI IN/OUT, AUX IN (stereo mini), MAIN OUTPUT (L/L+R, R), SUB (AUX) OUTPUT 1/2, Microphone/Guitar input, headphones, 2 x USB TO DEVICE, USB TO HOST, 2 x foot pedal' . "\n" . 'Bluetooth: Yes (depends on destination)' . "\n" . 'Audio Recorder: WAV and MP3 recording, 80 minutes per song' . "\n" . 'Dimensions (W x H x D): 1,017 x 139 x 431 mm' . "\n" . 'Weight: 11.6 kg' . "\n" . 'Power Supply: PA-300C or Yamaha-recommended equivalent' . "\n" . 'Power Consumption: 24 W', 'https://uk.yamaha.com/en/musical-instruments/keyboards/products/arranger-workstations/psr-sx920/' ),
		'yamaha-psr-sx720' => array( 'The PSR-SX720 is the mid-tier model in Yamaha\'s PSR-SX arranger workstation series, sharing the 61-key organ-style keyboard, 7-inch colour touchscreen and chassis of the flagship SX920 but with a smaller sound and style set. It offers 1,377 voices plus drum kits and XG voices, 450 accompaniment styles, Super Articulation+ and Super Articulation voices, and performance features including Chord Looper and Style Dynamics Control. It records and plays back WAV and MP3 audio to USB and has a microphone/guitar input, though it omits the SX920\'s vocal harmony engine.', 'Number of Keys: 61' . "\n" . 'Keyboard Type: Organ (FSB), Initial Touch' . "\n" . 'Touch Response: Normal, Soft1, Soft2, Hard1, Hard2' . "\n" . 'Display: TFT Color Wide VGA LCD, 800 x 480 dots (7 inch), touch screen' . "\n" . 'Tone Generating Technology: AWM Stereo Sampling' . "\n" . 'Maximum Polyphony: 128' . "\n" . 'Preset Voices: 1,377 Voices + 56 Drum/SFX Kits + 480 XG Voices' . "\n" . 'Featured Voices: 9 S.Articulation+, 252 S.Articulation, 55 OrganFlutes, 54 MegaVoice, 31 Sweet!, 87 Cool!, 131 Live!' . "\n" . 'Preset Styles: 450 (410 Pro, 37 Session, 3 Free Play)' . "\n" . 'Internal Memory: Approx. 1 GB' . "\n" . 'Expansion Voice Capacity: Approx. 1 GB' . "\n" . 'Amplifiers: 15 W x 2' . "\n" . 'Speakers: 13 cm x 2 + 5 cm x 2' . "\n" . 'Connectivity: MIDI IN/OUT, AUX IN (stereo mini), MAIN OUTPUT (L/L+R, R), Microphone/Guitar input, headphones, USB TO DEVICE, USB TO HOST, 2 x foot pedal' . "\n" . 'Audio Recorder: WAV and MP3 recording, 80 minutes per song' . "\n" . 'Dimensions (W x H x D): 1,017 x 139 x 431 mm' . "\n" . 'Weight: 11.6 kg' . "\n" . 'Power Supply: PA-300C or Yamaha-recommended equivalent' . "\n" . 'Power Consumption: 21 W', 'https://uk.yamaha.com/en/musical-instruments/keyboards/products/arranger-workstations/psr-sx720/' ),
		'yamaha-psr-sx700' => array( 'The PSR-SX700 is the mid-range model of the previous-generation PSR-SX arranger workstation line, sitting below the SX900. It has a 61-note organ-style keyboard, a 7-inch colour touchscreen, 986 voices with 41 drum and SFX kits, and 400 accompaniment styles including Pro, Session, DJ and Free Play types. It includes Super Articulation voices, VCM-quality DSP effects, Multi Pads, Playlist and Registration recall, a microphone/guitar input and USB WAV/MP3 audio recording and playback.', 'Number of Keys: 61' . "\n" . 'Keyboard Type: Organ (FSB), Initial Touch' . "\n" . 'Touch Response: Normal, Soft 1, Soft 2, Hard 1, Hard 2' . "\n" . 'Display: TFT Color Wide VGA LCD, 800 x 480 dots (7 inch), touch screen' . "\n" . 'Tone Generating Technology: AWM Stereo Sampling' . "\n" . 'Maximum Polyphony: 128' . "\n" . 'Preset Voices: 986 Voices + 41 Drum/SFX Kits' . "\n" . 'Featured Voices: 131 S.Art!, 30 MegaVoice, 31 Sweet!, 74 Cool!, 89 Live!, 24 Organ Flutes!' . "\n" . 'Preset Styles: 400 (353 Pro, 34 Session, 10 DJ, 3 Free Play)' . "\n" . 'Internal Memory: Approx. 1 GB' . "\n" . 'Expansion Voice Capacity: Approx. 400 MB' . "\n" . 'Multi Pad Banks: 226 banks x 4 pads' . "\n" . 'Amplifiers: 15 W x 2' . "\n" . 'Speakers: 13 cm x 2 + 5 cm x 2' . "\n" . 'Connectivity: MIDI IN/OUT, AUX IN (stereo mini), MAIN OUTPUT (L/L+R, R), Microphone/Guitar input x 1, headphones, USB TO DEVICE, USB TO HOST, 2 x foot pedal' . "\n" . 'Audio Recorder: WAV and MP3 recording, 80 minutes per song' . "\n" . 'Dimensions (W x H x D): 1,017 x 139 x 431 mm' . "\n" . 'Weight: 11.5 kg' . "\n" . 'Power Supply: PA-300C or Yamaha-recommended equivalent' . "\n" . 'Power Consumption: 21 W', 'https://uk.yamaha.com/en/musical-instruments/keyboards/products/arranger-workstations/psr-sx700/' ),
		'yamaha-psr-sx600' => array( 'The PSR-SX600 is the entry model in Yamaha\'s PSR-SX arranger range, aimed at home and stage players who want professional backing without the flagship price. It has 61 organ-style keys, a 4.3-inch colour display, 850 voices with 43 drum and SFX kits, and 415 styles spanning Pro, Session, DJ and Free Play types, plus 100 MB of onboard memory for expansion content. Distinctive features include Unison & Accent for style playback that follows your playing, Smart Chord one-finger accompaniment, two live control knobs, a microphone input and an upgraded DAC output stage.', 'Number of Keys: 61' . "\n" . 'Keyboard Type: Organ, Initial Touch' . "\n" . 'Touch Response: Normal, Soft 1, Soft 2, Hard 1, Hard 2' . "\n" . 'Display: TFT Color WQVGA LCD, 480 x 272 dots (4.3 inch)' . "\n" . 'Other Controllers: Pitch bend, modulation, 2 assignable control knobs' . "\n" . 'Tone Generating Technology: AWM Stereo Sampling' . "\n" . 'Maximum Polyphony: 128' . "\n" . 'Preset Voices: 850 Voices + 43 Drum/SFX Kits + 480 XG Voices' . "\n" . 'Featured Voices: 73 S.Articulation!, 27 MegaVoice, 27 Sweet!, 64 Cool!, 71 Live!' . "\n" . 'Preset Styles: 415 (372 Pro, 32 Session, 10 DJ, 1 Free Play)' . "\n" . 'Internal Memory: Approx. 20 MB max.' . "\n" . 'Expansion Voice Capacity: Approx. 100 MB max.' . "\n" . 'Multi Pad Banks: 188 banks x 4 pads' . "\n" . 'Amplifiers: 15 W x 2' . "\n" . 'Speakers: 12 cm x 2' . "\n" . 'Connectivity: AUX IN (stereo mini), MAIN OUTPUT (L/L+R, R), Microphone input x 1, headphones, USB TO DEVICE, USB TO HOST, 2 x foot pedal' . "\n" . 'Dimensions (W x H x D): 1,004 x 134 x 410 mm' . "\n" . 'Weight: 8.1 kg' . "\n" . 'Power Supply: PA-300C or Yamaha-recommended equivalent' . "\n" . 'Power Consumption: 17 W', 'https://uk.yamaha.com/en/musical-instruments/keyboards/products/arranger-workstations/psr-sx600/' ),
		'yamaha-psr-e473' => array( 'The PSR-E473 is the top model in Yamaha\'s PSR-E400 series of 61-key portable keyboards, pitched as an all-round instrument for learners that also holds up for experienced players. A newly developed tone generator provides 820 voices including Super Articulation Lite sounds, 290 styles and two channels of DSP insertion effects, with two live control knobs, a pitch bend wheel and Motion Effect for real-time sound shaping. Creative extras include Quick Sampling, Groove Creator, Mega Boost, a microphone input with vocal effects, individual left and right outputs and USB audio recording and interfacing.', 'Number of Keys: 61' . "\n" . 'Keyboard Type: Organ-style' . "\n" . 'Touch Response: Yes (Soft, Medium, Hard, Fixed)' . "\n" . 'Other Controllers: Pitch bend, articulation switches, 2 control knobs' . "\n" . 'Display: LCD with backlight' . "\n" . 'Tone Generating Technology: AWM Stereo Sampling' . "\n" . 'Maximum Polyphony: 64' . "\n" . 'Preset Voices: 820 (294 Panel + 28 Drum/SFX kits + 40 Arpeggio + 458 XGlite)' . "\n" . 'Featured Voices: 3 Live!, 9 Sweet!, 6 Cool!, 14 Super Articulation Lite' . "\n" . 'Effects: DSP1 41 types, DSP2 12 types, Reverb 12 types, Chorus 5 types, Master EQ 4 types' . "\n" . 'Preset Styles: 290 (Multi finger, Smart Chord fingering)' . "\n" . 'Groove Creator: 35 grooves, 5 sections each' . "\n" . 'Preset Songs: 30; user recording 10 songs, 6 tracks' . "\n" . 'Quick Sampling: 4 samples, approx. 9.6 sec, 44.1 kHz 16-bit stereo' . "\n" . 'USB Audio Recorder: WAV 44.1 kHz 16-bit stereo, up to 80 minutes per song' . "\n" . 'Internal Memory: Approx. 1.72 MB; external USB flash drive support' . "\n" . 'Connectivity: DC IN 12 V, AUX IN stereo mini, headphones, sustain pedal, USB TO DEVICE, USB TO HOST, 2 x standard phone OUTPUT, microphone input' . "\n" . 'Amplifiers: 6 W + 6 W' . "\n" . 'Speakers: 12 cm x 2' . "\n" . 'Dimensions (W x H x D): 992 x 136 x 404 mm' . "\n" . 'Weight: 7.0 kg (not including batteries)' . "\n" . 'Power Supply: PA-150 AC adaptor or six AA batteries' . "\n" . 'Power Consumption: 9 W (with PA-150 adaptor)', 'https://uk.yamaha.com/en/musical-instruments/keyboards/products/portable-keyboards/psr-e473/' ),
		'yamaha-ydp-105' => array( 'The ARIUS YDP-105 is Yamaha\'s entry-level 88-key cabinet digital piano, built around the weighted GHS keyboard with matte black keytops for a graded, acoustic-like touch. It keeps things simple with 10 voices, 10 piano preset songs, four reverb types, damper resonance and Dual and Duo modes, driven by a 6 W per channel amplifier and 12 cm stereo speakers. A sliding key cover, three-pedal unit, two headphone jacks and Smart Pianist app compatibility round out a piano designed for home practice.', 'Number of Keys: 88' . "\n" . 'Keyboard Type: GHS keyboard with matte black keytops' . "\n" . 'Touch Response: Hard / Medium / Soft / Fixed' . "\n" . 'Pedals: 3 - Damper (with half-pedal function), Sostenuto, Soft' . "\n" . 'Key Cover Style: Sliding' . "\n" . 'Piano Sound / Tone Generation: AWM Stereo Sampling' . "\n" . 'Damper Resonance: Yes' . "\n" . 'Maximum Polyphony: 64' . "\n" . 'Preset Voices: 10' . "\n" . 'Reverb: 4 types' . "\n" . 'Functions: Dual/Layers, Duo' . "\n" . 'Preset Songs: 10 voice demo songs + 10 piano preset songs' . "\n" . 'Metronome: Yes; Tempo range 32 - 280' . "\n" . 'Transpose: -6 to 0 to +6' . "\n" . 'Tuning: 414.8 - 440.0 - 466.8 Hz (approx. 0.2 Hz increments)' . "\n" . 'Connectivity: Headphones standard stereo phone jack x 2, USB TO HOST, DC IN 12 V' . "\n" . 'Amplifiers: 6 W x 2' . "\n" . 'Speakers: 12 cm x 2' . "\n" . 'Dimensions (W x H x D): 1,357 x 815 x 422 mm (height 969 mm with music rest raised)' . "\n" . 'Weight: 37.5 kg' . "\n" . 'Power Supply: PA-150 or Yamaha-recommended equivalent' . "\n" . 'Power Consumption: 6 W (with PA-150 adaptor)' . "\n" . 'Included Accessories: Owner\'s Manual, product registration, warranty, bench, power cord / AC adaptor (varies by area)', 'https://uk.yamaha.com/en/musical-instruments/pianos/products/arius/ydp-105/' ),
		'yamaha-p-145' => array( 'The P-145 is the entry-level model in Yamaha\'s P Series of portable digital pianos, with a slimmer, shorter body than its predecessor and a newly developed GHC (Graded Hammer Compact) 88-key weighted keyboard. It uses samples of the Yamaha CFIIIS concert grand with damper resonance, offering 10 voices, 64-note polyphony and 10 piano preset songs alongside Dual and Duo modes and a one-type Sound Boost. Oval 12 x 8 cm speakers driven by 7 W per channel, a USB TO HOST audio interface and compatibility with the optional LP-5A three-pedal unit make it suited to both practice and light stage use.', 'Number of Keys: 88' . "\n" . 'Keyboard Type: GHC keyboard with matte black keytops' . "\n" . 'Touch Sensitivity: Hard / Medium / Soft / Fixed' . "\n" . 'Piano Sound: Yamaha CFIIIS' . "\n" . 'Damper Resonance: Yes' . "\n" . 'Maximum Polyphony: 64' . "\n" . 'Preset Voices: 10' . "\n" . 'Reverb: 4 types' . "\n" . 'Sound Boost: 1 type' . "\n" . 'Functions: Dual/Layers, Duo' . "\n" . 'Preset Songs: 10 Voice Demo Songs + 10 Piano Preset Songs' . "\n" . 'Metronome: Yes; Tempo range 32 - 280' . "\n" . 'Transpose: -6 to 0 to +6' . "\n" . 'Tuning: 414.8 - 440.0 - 466.8 Hz (approx. 0.2 Hz increments)' . "\n" . 'USB Audio Interface: 44.1 kHz, 16 bit, stereo' . "\n" . 'Connectivity: Headphones standard stereo phone jack x 1, USB TO HOST, DC IN 12 V, sustain pedal, pedal unit' . "\n" . 'Amplifiers: 7 W x 2' . "\n" . 'Speakers: Oval (12 cm x 8 cm) x 2' . "\n" . 'Dimensions (W x H x D): 1,326 x 129 x 268 mm (with music rest: 307 mm high, 320 mm deep)' . "\n" . 'Weight: 11.1 kg' . "\n" . 'Power Supply: PA-150B or Yamaha-recommended equivalent (DC 12 V, 1.5 A)' . "\n" . 'Power Consumption: 6 W (with PA-150B adaptor)' . "\n" . 'Included Accessories: Owner\'s Manual, product registration, music rest, footswitch, AC adaptor (varies by area)' . "\n" . 'Optional Accessories: Keyboard stand L-100, pedal unit LP-5A, foot pedal FC3A, footswitch FC4A/FC5, keyboard bag SC-KB851, UD-BT01 wireless MIDI adaptor', 'https://uk.yamaha.com/en/musical-instruments/pianos/products/p-series/p-145/' ),
		'yamaha-sbp2f5' => array( 'The SBP2F5 is the larger of Yamaha\'s two Stage Custom Birch shell packs, a five-piece configuration built from 100% birch shells - the same material Yamaha uses on its higher-end kits - for a focused attack with controlled low end. The pack comprises a 22 x 17 inch bass drum, 16 x 15 inch floor tom, 12 x 8 and 10 x 7 inch toms, a 14 x 5.5 inch snare drum and a TH945C tom holder, with the toms mounted on Yamaha\'s Y.E.S.S. system so shell resonance is not choked. Shells use 6-ply 7.2 mm birch, 45-degree bearing edges, Absolute Lugs with an internal lock mechanism and Yamaha heads as standard. This is a shell pack: cymbals, stands, pedal and throne are not included.', 'Shell Pack Model: SBP2F5' . "\n" . 'Shell: Birch, 6 ply, 7.2 mm' . "\n" . 'Bearing Edge: 45 degrees / R1.5' . "\n" . 'Tom and Floor Tom Hoop: 1.5 mm Triple Flange Hoop (Steel)' . "\n" . 'Bass Drum Hoop: Wood hoop' . "\n" . 'Lug: Absolute Lug with Internal Lug Lock Mechanism' . "\n" . 'Tom Mount: Y.E.S.S. (Yamaha Enhanced Sustain System)' . "\n" . 'Tom / Floor Tom Heads: Top Yamaha Clear, Bottom Yamaha Clear' . "\n" . 'Bass Drum Heads: Front Yamaha Black with ring mute, Batter Yamaha Clear with ring mute' . "\n" . 'Bass Drum: 22 in x 17 in (SBB2217)' . "\n" . 'Floor Tom: 16 in x 15 in (SBF1615)' . "\n" . 'Tom Tom: 12 in x 8 in (SBT1208)' . "\n" . 'Tom Tom: 10 in x 7 in (SBT1007)' . "\n" . 'Snare Drum: 14 in x 5.5 in (SBS1455)' . "\n" . 'Tom Holder: TH945C', 'https://europe.yamaha.com/en/musical-instruments/drums/products/drum-sets/stage-custom-birch/' ),
	);
}
